-- Bilingual, place-specific editorial enrichment for every published oddity-category place.
-- Research reviewed on 2026-10-28; private, closed, seasonal and scheduled-access sites are identified explicitly.
CREATE TABLE IF NOT EXISTS place_editorial_sources (place_id TEXT NOT NULL REFERENCES places(id) ON DELETE CASCADE, source_url TEXT NOT NULL, source_kind TEXT NOT NULL DEFAULT 'official-or-authoritative', verified_at TEXT NOT NULL, PRIMARY KEY(place_id, source_url));
CREATE INDEX IF NOT EXISTS idx_editorial_sources_place ON place_editorial_sources(place_id);

UPDATE places SET description_en='10 Downing Street has been the official residence and office of Britain’s prime ministers since 1735. The familiar black door is set behind security gates in Whitehall, so the public view is distant and the Georgian terrace is more extensive than its television image suggests.', description_it='10 Downing Street è residenza ufficiale e ufficio dei primi ministri britannici dal 1735. La celebre porta nera si trova dietro i cancelli di sicurezza di Whitehall: la vista pubblica è distante e la terrazza georgiana è molto più estesa di quanto sembri in televisione.', editorial_hook_en='10 Downing Street: 10 Downing Street has been the official residence and office of Britain’s prime ministers since 1735.', editorial_hook_it='10 Downing Street: 10 Downing Street è residenza ufficiale e ufficio dei primi ministri britannici dal 1735.', access_notes_en='Private property: view respectfully from public space and do not disturb residents or staff.', access_notes_it='Proprietà privata: osserva con rispetto dallo spazio pubblico senza disturbare residenti o personale.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.gov.uk/government/history/10-downing-street' WHERE id='LA-4153F4E9' AND category='ODDITY';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://www.gov.uk/government/history/10-downing-street','official-or-authoritative','2026-10-28' FROM places WHERE id='LA-4153F4E9' ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='The Freston Road railway arches appear in the video for Rick Astley’s 1987 hit Never Gonna Give You Up. The location anchors a globally familiar pop performance in the ordinary industrial streetscape of North Kensington, though later redevelopment has altered parts of the scene.', description_it='Gli archi ferroviari di Freston Road compaiono nel video del successo di Rick Astley del 1987 Never Gonna Give You Up. Il luogo lega una performance pop conosciuta in tutto il mondo al paesaggio industriale quotidiano di North Kensington, in parte modificato da interventi successivi.', editorial_hook_en='148 Freston Rd: The Freston Road railway arches appear in the video for Rick Astley’s 1987 hit Never Gonna Give You Up.', editorial_hook_it='148 Freston Rd: Gli archi ferroviari di Freston Road compaiono nel video del successo di Rick Astley del 1987 Never Gonna Give You Up.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-9C502E07' AND category='ODDITY';
