UPDATE places SET description_en='The Seven Dials water clock projects from the façade at 21–23 Short’s Gardens. Designed as a kinetic public artwork, its figures and mechanisms mark the time with moving water, turning a corner of Covent Garden into a small piece of mechanical theatre.', description_it='L’orologio ad acqua di Seven Dials sporge dalla facciata al 21–23 Short’s Gardens. Progettato come opera pubblica cinetica, segna il tempo con figure, meccanismi e acqua in movimento, trasformando un angolo di Covent Garden in un piccolo teatro meccanico.', editorial_hook_en='21-23 Short''s Gardens: The Seven Dials water clock projects from the façade at 21–23 Short’s Gardens.', editorial_hook_it='21-23 Short''s Gardens: L’orologio ad acqua di Seven Dials sporge dalla facciata al 21–23 Short’s Gardens.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-39B28B3C' AND category='ODDITY';
