UPDATE places SET description_en='Singer Amy Winehouse lived and died at this Camden Square house in 2011. The building remains a private residence, while the address has become an informal place of remembrance connected to her distinctive voice, troubled public life and deep association with Camden.', description_it='La cantante Amy Winehouse visse e morì in questa casa di Camden Square nel 2011. L’edificio resta un’abitazione privata, mentre l’indirizzo è diventato un luogo informale della memoria legato alla sua voce inconfondibile, alla difficile vita pubblica e al forte rapporto con Camden.', editorial_hook_en='30 Camden Square: Singer Amy Winehouse lived and died at this Camden Square house in 2011.', editorial_hook_it='30 Camden Square: La cantante Amy Winehouse visse e morì in questa casa di Camden Square nel 2011.', access_notes_en='Private property: view respectfully from public space and do not disturb residents or staff.', access_notes_it='Proprietà privata: osserva con rispetto dallo spazio pubblico senza disturbare residenti o personale.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-6E634A42' AND category='ODDITY';
