UPDATE places SET description_en='Abbey Mills Pumping Station was designed by Joseph Bazalgette’s engineers in the 1860s as part of London’s new sewer system. Its lavish Byzantine-inspired towers and polychrome brickwork earned it the nickname ‘Cathedral of Sewage’, disguising heavy pumping machinery within an exceptionally ornate industrial monument.', description_it='Abbey Mills Pumping Station fu progettata dagli ingegneri di Joseph Bazalgette negli anni Sessanta dell’Ottocento per il nuovo sistema fognario londinese. Torri d’ispirazione bizantina e mattoni policromi le valsero il soprannome di “Cattedrale delle Fogne”, celando grandi macchinari in un monumento industriale eccezionalmente ornato.', editorial_hook_en='Abbey Mills Pumping Station: Abbey Mills Pumping Station was designed by Joseph Bazalgette’s engineers in the 1860s as part of London’s new sewer system.', editorial_hook_it='Abbey Mills Pumping Station: Abbey Mills Pumping Station fu progettata dagli ingegneri di Joseph Bazalgette negli anni Sessanta dell’Ottocento per il nuovo sistema fognario londinese.', access_notes_en='Interior access is scheduled, ticketed or event-led; check the official venue before travelling.', access_notes_it='L’accesso interno è programmato, a pagamento o legato a eventi: controlla il sito ufficiale prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-5F918E8C' AND category='ODDITY';
