SELECT id,'https://www.google.com/maps?q=51.5300806,-0.000596','official-or-authoritative','2026-10-28' FROM places WHERE id='LA-5F918E8C' ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='The zebra crossing outside Abbey Road Studios became one of music’s most imitated images after appearing on the Beatles’ 1969 album cover. It remains a working road crossing, not a film set, and visitors should use it normally without stopping traffic or blocking residents.', description_it='Le strisce pedonali davanti agli Abbey Road Studios divennero una delle immagini musicali più imitate dopo la copertina dell’album dei Beatles del 1969. Restano un attraversamento stradale in uso, non un set: vanno utilizzate normalmente senza fermare il traffico o intralciare i residenti.', editorial_hook_en='Abbey Rd crossing: The zebra crossing outside Abbey Road Studios became one of music’s most imitated images after appearing on the Beatles’ 1969 album cover.', editorial_hook_it='Abbey Rd crossing: Le strisce pedonali davanti agli Abbey Road Studios divennero una delle immagini musicali più imitate dopo la copertina dell’album dei Beatles del 1969.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.abbeyroad.com/crossing' WHERE id='LA-B6DA5A6E' AND category='ODDITY';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://www.abbeyroad.com/crossing','official-or-authoritative','2026-10-28' FROM places WHERE id='LA-B6DA5A6E' ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='Agatha Christie lived in this Chelsea house during a productive period of her career. The blue plaque turns a private stucco façade into a precise literary landmark connected to the creator of Hercule Poirot and Miss Marple; the interior is not a visitor attraction.', description_it='Agatha Christie abitò in questa casa di Chelsea durante un periodo produttivo della sua carriera. La targa blu trasforma una facciata privata in un preciso luogo letterario legato alla creatrice di Hercule Poirot e Miss Marple; l’interno non è visitabile.', editorial_hook_en='Agatha Christie''s house: Agatha Christie lived in this Chelsea house during a productive period of her career.', editorial_hook_it='Agatha Christie''s house: Agatha Christie abitò in questa casa di Chelsea durante un periodo produttivo della sua carriera.', access_notes_en='Private property: view respectfully from public space and do not disturb residents or staff.', access_notes_it='Proprietà privata: osserva con rispetto dallo spazio pubblico senza disturbare residenti o personale.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-943A9610' AND category='ODDITY';
