UPDATE places SET description_en='Aldgate Pump marks an old water source at the eastern edge of the City. Its present cast-iron form dates from the nineteenth century, and the wolf’s-head spout recalls the last wolf said to have been killed nearby; contaminated water from the pump also became notorious in Victorian health investigations.', description_it='Aldgate Pump indica un’antica fonte d’acqua al margine orientale della City. L’attuale struttura in ghisa è ottocentesca e il beccuccio a testa di lupo ricorda l’ultimo lupo che si dice ucciso nei dintorni; l’acqua contaminata della pompa divenne inoltre nota nelle indagini sanitarie vittoriane.', editorial_hook_en='Aldgate Pump: Aldgate Pump marks an old water source at the eastern edge of the City.', editorial_hook_it='Aldgate Pump: Aldgate Pump indica un’antica fonte d’acqua al margine orientale della City.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-FA8C4BAA' AND category='ODDITY';
