UPDATE places SET description_en='Annabel’s is a private members’ club founded by Mark Birley in 1963 and now housed in a richly decorated Berkeley Square townhouse. Its changing floral façades are public spectacles, but the theatrical interiors, restaurants and nightclub remain accessible only to members and their guests.', description_it='Annabel’s è un club privato fondato da Mark Birley nel 1963 e oggi ospitato in una townhouse riccamente decorata di Berkeley Square. Le installazioni floreali sulla facciata sono spettacoli pubblici, ma gli interni teatrali, i ristoranti e il nightclub restano riservati ai soci e ai loro ospiti.', editorial_hook_en='Annabel''s: Annabel’s is a private members’ club founded by Mark Birley in 1963 and now housed in a richly decorated Berkeley Square townhouse.', editorial_hook_it='Annabel''s: Annabel’s è un club privato fondato da Mark Birley nel 1963 e oggi ospitato in una townhouse riccamente decorata di Berkeley Square.', access_notes_en='Private property: view respectfully from public space and do not disturb residents or staff.', access_notes_it='Proprietà privata: osserva con rispetto dallo spazio pubblico senza disturbare residenti o personale.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.annabels.co.uk/' WHERE id='LA-8AE5679E' AND category='ODDITY';
