UPDATE places SET description_en='Anish Kapoor and Cecil Balmond’s ArcelorMittal Orbit was built for the 2012 Olympic Park as a looping red-steel observation tower. Its deliberately unstable-looking structure contains viewing platforms and the later-added tunnel slide, combining public art, engineering and an unconventional visitor ride.', description_it='L’ArcelorMittal Orbit di Anish Kapoor e Cecil Balmond fu costruito per il Parco Olimpico del 2012 come torre panoramica di acciaio rosso avvolto su se stesso. La struttura volutamente instabile contiene piattaforme e il successivo scivolo a tunnel, unendo arte pubblica, ingegneria e attrazione.', editorial_hook_en='ArcelorMittal Orbit: Anish Kapoor and Cecil Balmond’s ArcelorMittal Orbit was built for the 2012 Olympic Park as a looping red-steel observation tower.', editorial_hook_it='ArcelorMittal Orbit: L’ArcelorMittal Orbit di Anish Kapoor e Cecil Balmond fu costruito per il Parco Olimpico del 2012 come torre panoramica di acciaio rosso avvolto su se stesso.', access_notes_en='Interior access is scheduled, ticketed or event-led; check the official venue before travelling.', access_notes_it='L’accesso interno è programmato, a pagamento o legato a eventi: controlla il sito ufficiale prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.queenelizabetholympicpark.co.uk/things-to-do/arcelormittal-orbit' WHERE id='LA-881EE9B2' AND category='ODDITY';
