UPDATE places SET description_en='Babylon Park is an underground, space-themed amusement arcade beneath Camden Market. Neon planets, rides, games and soft-play areas create a deliberately immersive interior for families; it is a commercial entertainment venue rather than a historic oddity, and entry arrangements vary by activity.', description_it='Babylon Park è un parco divertimenti sotterraneo a tema spaziale sotto Camden Market. Pianeti al neon, giostre, giochi e aree morbide creano un interno volutamente immersivo per famiglie; è un locale commerciale, non una curiosità storica, e le modalità d’ingresso variano secondo l’attività.', editorial_hook_en='Babylon Park London: Babylon Park is an underground, space-themed amusement arcade beneath Camden Market.', editorial_hook_it='Babylon Park London: Babylon Park è un parco divertimenti sotterraneo a tema spaziale sotto Camden Market.', access_notes_en='Interior access is scheduled, ticketed or event-led; check the official venue before travelling.', access_notes_it='L’accesso interno è programmato, a pagamento o legato a eventi: controlla il sito ufficiale prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://babylonpark.com/london/' WHERE id='LA-6A494E1A' AND category='ODDITY';
