UPDATE places SET description_en='Bacherozzo is the affectionate local nickname attached to a large insect-like sculpture near Fitzrovia. Its enlarged body and legs turn an easily overlooked urban corner into a surreal encounter; inspect the work itself for artist and title information rather than assuming it depicts a specific species.', description_it='Bacherozzo è il soprannome affettuoso dato a una grande scultura simile a un insetto vicino a Fitzrovia. Corpo e zampe ingranditi trasformano un angolo urbano facile da ignorare in un incontro surreale; conviene leggere sul posto autore e titolo senza attribuirle una specie precisa.', editorial_hook_en='Bacherozzo: Bacherozzo is the affectionate local nickname attached to a large insect-like sculpture near Fitzrovia.', editorial_hook_it='Bacherozzo: Bacherozzo è il soprannome affettuoso dato a una grande scultura simile a un insetto vicino a Fitzrovia.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-B35CA19A' AND category='ODDITY';
