UPDATE places SET description_en='Banksy’s 2017 mural near the Barbican responds to Jean-Michel Basquiat’s exhibition with a crowned figure being searched by police. The stencil deliberately collides Basquiat’s visual language with surveillance and institutional approval, and survives as a protected street artwork near the cultural complex.', description_it='Il murale di Banksy del 2017 vicino al Barbican risponde alla mostra di Jean-Michel Basquiat con una figura incoronata perquisita dalla polizia. Lo stencil mette volutamente in collisione il linguaggio visivo di Basquiat con sorveglianza e approvazione istituzionale, sopravvivendo come opera di strada protetta.', editorial_hook_en='Banksy Basquiat: Banksy’s 2017 mural near the Barbican responds to Jean-Michel Basquiat’s exhibition with a crowned figure being searched by police.', editorial_hook_it='Banksy Basquiat: Il murale di Banksy del 2017 vicino al Barbican risponde alla mostra di Jean-Michel Basquiat con una figura incoronata perquisita dalla polizia.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://banksyexplained.com/basquiat-murals-2017/' WHERE id='O16' AND category='ODDITY';
