UPDATE places SET description_en='This surviving Banksy work emerged from the long graffiti rivalry between Banksy and London writer King Robbo. Layers of alteration, restoration and commentary make the wall a document of street-art authorship and territorial dispute rather than a pristine single-artist mural.', description_it='Quest’opera superstite di Banksy nasce dalla lunga rivalità nel graffiti writing tra Banksy e l’artista londinese King Robbo. Strati di modifiche, restauri e commenti trasformano il muro in un documento su autorialità e territorio nella street art, non in un murale intatto di un solo autore.', editorial_hook_en='Banksy I love London Robbo: This surviving Banksy work emerged from the long graffiti rivalry between Banksy and London writer King Robbo.', editorial_hook_it='Banksy I love London Robbo: Quest’opera superstite di Banksy nasce dalla lunga rivalità nel graffiti writing tra Banksy e l’artista londinese King Robbo.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-386C8C34' AND category='ODDITY';
