UPDATE places SET description_en='The Barbican Conservatory wraps tropical planting around the concrete fly-tower and backstage structures of the Barbican Centre. More than 1,500 plant species, pools and fish occupy London’s second-largest conservatory, usually opened only on selected dates with timed entry.', description_it='Il Barbican Conservatory avvolge di vegetazione tropicale la torre scenica e le strutture di servizio in cemento del Barbican Centre. Oltre 1.500 specie, vasche e pesci occupano la seconda serra più grande di Londra, normalmente aperta soltanto in date selezionate con ingresso a orario.', editorial_hook_en='Barbican Conservatory: The Barbican Conservatory wraps tropical planting around the concrete fly-tower and backstage structures of the Barbican Centre.', editorial_hook_it='Barbican Conservatory: Il Barbican Conservatory avvolge di vegetazione tropicale la torre scenica e le strutture di servizio in cemento del Barbican Centre.', access_notes_en='Access is seasonal or limited to selected open days; confirm the current programme before travelling.', access_notes_it='L’accesso è stagionale o limitato a giornate specifiche: verifica il programma prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.barbican.org.uk/whats-on/2026/series/visit-the-conservatory' WHERE id='O4' AND category='ODDITY';
