UPDATE places SET description_en='Barnet Physic Well is a seventeenth-century medicinal spring once promoted for its purging waters and visited by Samuel Pepys. The small well house preserves the source beneath suburban Barnet, but interior access is normally limited to organised openings rather than daily visits.', description_it='Barnet Physic Well è una sorgente medicinale seicentesca, un tempo pubblicizzata per le sue acque purgative e visitata da Samuel Pepys. Il piccolo edificio conserva la fonte sotto la Barnet suburbana, ma l’interno è normalmente accessibile solo durante aperture organizzate.', editorial_hook_en='Barnet Physic Well: Barnet Physic Well is a seventeenth-century medicinal spring once promoted for its purging waters and visited by Samuel Pepys.', editorial_hook_it='Barnet Physic Well: Barnet Physic Well è una sorgente medicinale seicentesca, un tempo pubblicizzata per le sue acque purgative e visitata da Samuel Pepys.', access_notes_en='Access is seasonal or limited to selected open days; confirm the current programme before travelling.', access_notes_it='L’accesso è stagionale o limitato a giornate specifiche: verifica il programma prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-679640E0' AND category='ODDITY';
