UPDATE places SET description_en='Antony Gormley’s ROOM is a giant crouching figure attached to the Beaumont Hotel, with a single inhabitable bedroom concealed inside its cuboid body. From the street it reads as monumental public sculpture; the dark, austere interior is a private hotel suite.', description_it='ROOM di Antony Gormley è una gigantesca figura accovacciata addossata al Beaumont Hotel, con una camera abitabile nascosta nel corpo cubico. Dalla strada appare come scultura pubblica monumentale; l’interno scuro e austero è invece una suite privata dell’hotel.', editorial_hook_en='Beaumont Hotel Robot Statue: Antony Gormley’s ROOM is a giant crouching figure attached to the Beaumont Hotel, with a single inhabitable bedroom concealed inside its cuboid body.', editorial_hook_it='Beaumont Hotel Robot Statue: ROOM di Antony Gormley è una gigantesca figura accovacciata addossata al Beaumont Hotel, con una camera abitabile nascosta nel corpo cubico.', access_notes_en='Private property: view respectfully from public space and do not disturb residents or staff.', access_notes_it='Proprietà privata: osserva con rispetto dallo spazio pubblico senza disturbare residenti o personale.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.thebeaumont.com/room-by-antony-gormley' WHERE id='LA-487F8D48' AND category='ODDITY';
