UPDATE places SET description_en='Beavers have returned to west London through a managed reintroduction project in the Paradise Fields wetlands. Their dams, gnawed trunks and changing water channels are more reliably seen than the nocturnal animals themselves, demonstrating how one species can reshape an urban habitat.', description_it='I castori sono tornati nella Londra occidentale grazie a un progetto controllato di reintroduzione nelle zone umide di Paradise Fields. Dighe, tronchi rosicchiati e canali modificati si osservano più facilmente degli animali notturni e mostrano come una sola specie possa trasformare un habitat urbano.', editorial_hook_en='Beavers: Beavers have returned to west London through a managed reintroduction project in the Paradise Fields wetlands.', editorial_hook_it='Beavers: I castori sono tornati nella Londra occidentale grazie a un progetto controllato di reintroduzione nelle zone umide di Paradise Fields.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-144953E7' AND category='ODDITY';
