UPDATE places SET description_en='Big Ben is properly the nickname of the Great Bell inside Elizabeth Tower, not the tower or clock as a whole. Augustus Pugin designed the clock dials and Gothic detailing for Charles Barry’s Palace of Westminster; tours climb hundreds of steps to the mechanism and belfry.', description_it='Big Ben è propriamente il soprannome della Great Bell dentro Elizabeth Tower, non della torre o dell’orologio nel suo complesso. Augustus Pugin progettò quadranti e dettagli gotici per il Palace of Westminster di Charles Barry; le visite salgono centinaia di gradini fino al meccanismo e alla cella campanaria.', editorial_hook_en='Big Ben: Big Ben is properly the nickname of the Great Bell inside Elizabeth Tower, not the tower or clock as a whole.', editorial_hook_it='Big Ben: Big Ben è propriamente il soprannome della Great Bell dentro Elizabeth Tower, non della torre o dell’orologio nel suo complesso.', access_notes_en='Interior access is scheduled, ticketed or event-led; check the official venue before travelling.', access_notes_it='L’accesso interno è programmato, a pagamento o legato a eventi: controlla il sito ufficiale prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.parliament.uk/visiting/visiting-and-tours/big-ben-tour/' WHERE id='LA-DE3494DB' AND category='ODDITY';
