UPDATE places SET description_en='The blue plaque marks the Chelsea home of Bram Stoker, author of Dracula and theatre manager to Henry Irving. It links a conventional nineteenth-century terrace to the professional theatrical world and imaginative sources behind one of literature’s most enduring Gothic figures.', description_it='La targa blu indica la casa di Chelsea di Bram Stoker, autore di Dracula e direttore teatrale al fianco di Henry Irving. Collega una normale terrazza ottocentesca al mondo professionale del teatro e alle fonti creative di una delle figure gotiche più durature della letteratura.', editorial_hook_en='Blue Plaque: Bram Stoker: The blue plaque marks the Chelsea home of Bram Stoker, author of Dracula and theatre manager to Henry Irving.', editorial_hook_it='Blue Plaque: Bram Stoker: La targa blu indica la casa di Chelsea di Bram Stoker, autore di Dracula e direttore teatrale al fianco di Henry Irving.', access_notes_en='Private property: view respectfully from public space and do not disturb residents or staff.', access_notes_it='Proprietà privata: osserva con rispetto dallo spazio pubblico senza disturbare residenti o personale.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.english-heritage.org.uk/visit/blue-plaques/bram-stoker/' WHERE id='LA-65495C28' AND category='ODDITY';
