UPDATE places SET description_en='Bridge Pool is a small tidal or riverside remnant beside the Thames path in Nine Elms, where engineered embankments meet older water infrastructure. Its interest lies in reading the surviving basin and surrounding redevelopment together rather than expecting a conventional ornamental pond.', description_it='Bridge Pool è un piccolo residuo fluviale o di marea lungo il percorso del Tamigi a Nine Elms, dove argini ingegnerizzati incontrano infrastrutture idrauliche più antiche. L’interesse sta nel leggere insieme il bacino superstite e la riqualificazione circostante, non nell’aspettarsi un laghetto ornamentale.', editorial_hook_en='Bridge Pool: Bridge Pool is a small tidal or riverside remnant beside the Thames path in Nine Elms, where engineered embankments meet older water infrastructure.', editorial_hook_it='Bridge Pool: Bridge Pool è un piccolo residuo fluviale o di marea lungo il percorso del Tamigi a Nine Elms, dove argini ingegnerizzati incontrano infrastrutture idrauliche più antiche.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-EB43F217' AND category='ODDITY';
