UPDATE places SET description_en='Brixton Windmill, also called Ashby’s Mill, was built in 1816 and later adapted to steam-powered milling when surrounding development blocked the wind. Restored machinery and volunteer-led tours explain how flour was produced inside a rare surviving tower mill in inner London.', description_it='Brixton Windmill, detta anche Ashby’s Mill, fu costruita nel 1816 e successivamente adattata alla macinazione a vapore quando gli edifici circostanti bloccarono il vento. Macchinari restaurati e visite di volontari spiegano la produzione di farina in un raro mulino a torre sopravvissuto nella Londra interna.', editorial_hook_en='Brixton Windmill: Brixton Windmill, also called Ashby’s Mill, was built in 1816 and later adapted to steam-powered milling when surrounding development blocked the wind.', editorial_hook_it='Brixton Windmill: Brixton Windmill, detta anche Ashby’s Mill, fu costruita nel 1816 e successivamente adattata alla macinazione a vapore quando gli edifici circostanti bloccarono il vento.', access_notes_en='Access is seasonal or limited to selected open days; confirm the current programme before travelling.', access_notes_it='L’accesso è stagionale o limitato a giornate specifiche: verifica il programma prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.brixtonwindmill.org/' WHERE id='O5' AND category='ODDITY';
