UPDATE places SET description_en='Brown Hart Gardens is an elevated public terrace built in 1906 over the former Duke Street electricity substation. Its Baroque stone pavilion, vents and raised platform reveal the infrastructure beneath, while later planting and seating turned the roof into an unusual Mayfair garden.', description_it='Brown Hart Gardens è una terrazza pubblica sopraelevata costruita nel 1906 sull’ex sottostazione elettrica di Duke Street. Padiglione barocco, prese d’aria e piattaforma rivelano l’infrastruttura sottostante, mentre piante e sedute aggiunte in seguito hanno trasformato il tetto in un insolito giardino di Mayfair.', editorial_hook_en='Brown Hart Gardens: Brown Hart Gardens is an elevated public terrace built in 1906 over the former Duke Street electricity substation.', editorial_hook_it='Brown Hart Gardens: Brown Hart Gardens è una terrazza pubblica sopraelevata costruita nel 1906 sull’ex sottostazione elettrica di Duke Street.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.westminster.gov.uk/parks-and-open-spaces/brown-hart-gardens' WHERE id='O3' AND category='ODDITY';
