UPDATE places SET description_en='The BT Tower was completed in 1964 as the hub of Britain’s microwave telecommunications network. Its cylindrical form carried aerials above surrounding buildings and its rotating restaurant became a symbol of technological optimism; the tower is being converted to a hotel and is not generally open.', description_it='La BT Tower fu completata nel 1964 come nodo della rete britannica di telecomunicazioni a microonde. La forma cilindrica portava antenne sopra gli edifici e il ristorante girevole divenne simbolo di ottimismo tecnologico; la torre è in trasformazione alberghiera e non è normalmente aperta.', editorial_hook_en='BT Tower: The BT Tower was completed in 1964 as the hub of Britain’s microwave telecommunications network.', editorial_hook_it='BT Tower: La BT Tower fu completata nel 1964 come nodo della rete britannica di telecomunicazioni a microonde.', access_notes_en='Private property: view respectfully from public space and do not disturb residents or staff.', access_notes_it='Proprietà privata: osserva con rispetto dallo spazio pubblico senza disturbare residenti o personale.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-64498687' AND category='ODDITY';
