UPDATE places SET description_en='Burlington Arcade opened in 1819 as one of London’s earliest covered shopping passages. Uniformed beadles still enforce traditional rules beneath the glazed roof, while the narrow sequence of small luxury shops preserves the scale and controlled atmosphere of a Regency arcade.', description_it='Burlington Arcade aprì nel 1819 come uno dei primi passaggi commerciali coperti di Londra. I beadles in uniforme applicano ancora regole tradizionali sotto il tetto vetrato, mentre la stretta sequenza di boutique conserva scala e atmosfera controllata di una galleria Regency.', editorial_hook_en='Burlington Arcade: Burlington Arcade opened in 1819 as one of London’s earliest covered shopping passages.', editorial_hook_it='Burlington Arcade: Burlington Arcade aprì nel 1819 come uno dei primi passaggi commerciali coperti di Londra.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-D2A6F68E' AND category='ODDITY';
