UPDATE places SET description_en='The Cable Street Mural commemorates the 1936 confrontation in which local communities blocked Oswald Mosley’s British Union of Fascists. Painted by several artists from the late 1970s onward, its sweeping battle scene turns the wall of St George’s Town Hall into a monument to organised resistance.', description_it='Il Cable Street Mural commemora lo scontro del 1936, quando le comunità locali impedirono il passaggio alla British Union of Fascists di Oswald Mosley. Dipinta da vari artisti dalla fine degli anni Settanta, la grande scena trasforma il muro di St George’s Town Hall in un monumento alla resistenza organizzata.', editorial_hook_en='Cable Street Mural: The Cable Street Mural commemorates the 1936 confrontation in which local communities blocked Oswald Mosley’s British Union of Fascists.', editorial_hook_it='Cable Street Mural: Il Cable Street Mural commemora lo scontro del 1936, quando le comunità locali impedirono il passaggio alla British Union of Fascists di Oswald Mosley.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-C8BB49A6' AND category='ODDITY';
