UPDATE places SET description_en='Caesar’s Camp is an Iron Age hillfort earthwork on Wimbledon Common, despite the later name linking it to Julius Caesar. Banks and ditches survive among woodland and paths, offering archaeological evidence of a defended settlement rather than a Roman military camp.', description_it='Caesar’s Camp è un terrapieno fortificato dell’età del Ferro su Wimbledon Common, nonostante il nome successivo lo colleghi a Giulio Cesare. Argini e fossati sopravvivono tra bosco e sentieri, offrendo prove archeologiche di un insediamento difeso e non di un campo militare romano.', editorial_hook_en='Caesar''s Camp: Caesar’s Camp is an Iron Age hillfort earthwork on Wimbledon Common, despite the later name linking it to Julius Caesar.', editorial_hook_it='Caesar''s Camp: Caesar’s Camp è un terrapieno fortificato dell’età del Ferro su Wimbledon Common, nonostante il nome successivo lo colleghi a Giulio Cesare.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-9274D771' AND category='ODDITY';
