UPDATE places SET description_en='Caesar’s Well is a spring near the Iron Age earthworks of Caesar’s Camp on Wimbledon Common. The stone-lined source once supplied local water and later fed a cistern; its Roman-sounding name is folklore rather than evidence of a connection to Julius Caesar.', description_it='Caesar’s Well è una sorgente vicino ai terrapieni dell’età del Ferro di Caesar’s Camp su Wimbledon Common. La fonte rivestita in pietra forniva acqua locale e in seguito alimentò una cisterna; il nome romano appartiene alla leggenda, non prova un legame con Giulio Cesare.', editorial_hook_en='Caesar''s Well: Caesar’s Well is a spring near the Iron Age earthworks of Caesar’s Camp on Wimbledon Common.', editorial_hook_it='Caesar''s Well: Caesar’s Well è una sorgente vicino ai terrapieni dell’età del Ferro di Caesar’s Camp su Wimbledon Common.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.wimbledonandputneycommons.org.uk/' WHERE id='O2' AND category='ODDITY';
