UPDATE places SET description_en='This unusually narrow house in Cambridge Gardens exploits a constrained Notting Hill plot with a façade only a few metres wide. Its stacked rooms and compressed street presence demonstrate how London builders turned leftover urban land into habitable architecture.', description_it='Questa casa insolitamente stretta di Cambridge Gardens sfrutta un lotto limitato di Notting Hill con una facciata larga pochi metri. Stanze sovrapposte e presenza compressa sulla strada mostrano come i costruttori londinesi trasformassero residui di terreno urbano in architettura abitabile.', editorial_hook_en='Cambridge Gdns thin house: This unusually narrow house in Cambridge Gardens exploits a constrained Notting Hill plot with a façade only a few metres wide.', editorial_hook_it='Cambridge Gdns thin house: Questa casa insolitamente stretta di Cambridge Gardens sfrutta un lotto limitato di Notting Hill con una facciata larga pochi metri.', access_notes_en='Private property: view respectfully from public space and do not disturb residents or staff.', access_notes_it='Proprietà privata: osserva con rispetto dallo spazio pubblico senza disturbare residenti o personale.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-13BCF732' AND category='ODDITY';
