UPDATE places SET description_en='This Spitalfields building presents two contrasting façades, making one structure read like neighbouring houses from different periods. The visual split reflects adaptation within a densely layered conservation area, where altered fronts often conceal connected interiors and older fabric.', description_it='Questo edificio di Spitalfields presenta due facciate contrastanti, facendo apparire un’unica struttura come case vicine di epoche diverse. La divisione visiva riflette gli adattamenti in un’area storica stratificata, dove fronti modificati nascondono spesso interni collegati e tessuti più antichi.', editorial_hook_en='Casa doppia facciata: This Spitalfields building presents two contrasting façades, making one structure read like neighbouring houses from different periods.', editorial_hook_it='Casa doppia facciata: Questo edificio di Spitalfields presenta due facciate contrastanti, facendo apparire un’unica struttura come case vicine di epoche diverse.', access_notes_en='Private property: view respectfully from public space and do not disturb residents or staff.', access_notes_it='Proprietà privata: osserva con rispetto dallo spazio pubblico senza disturbare residenti o personale.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-C11D1D90' AND category='ODDITY';
