UPDATE places SET description_en='Castle Farm near Shoreham in Kent is a working lavender farm rather than a London attraction. Summer fields, distillation and farm-shop products explain the agricultural source of lavender oil, but flowering, tickets and access are seasonal and the site lies well beyond Greater London.', description_it='Castle Farm vicino a Shoreham, nel Kent, è una fattoria di lavanda attiva e non un’attrazione londinese. Campi estivi, distillazione e prodotti del negozio mostrano l’origine agricola dell’olio di lavanda, ma fioritura, biglietti e accesso sono stagionali e il sito è fuori dalla Greater London.', editorial_hook_en='Castle Farm: Castle Farm near Shoreham in Kent is a working lavender farm rather than a London attraction.', editorial_hook_it='Castle Farm: Castle Farm vicino a Shoreham, nel Kent, è una fattoria di lavanda attiva e non un’attrazione londinese.', access_notes_en='Access is seasonal or limited to selected open days; confirm the current programme before travelling.', access_notes_it='L’accesso è stagionale o limitato a giornate specifiche: verifica il programma prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.castlefarmkent.co.uk/' WHERE id='LA-8C880220' AND category='ODDITY';
