UPDATE places SET description_en='The plaque marks Charlie Chaplin’s South London beginnings, linking an ordinary streetscape to the childhood poverty and music-hall culture that shaped one of cinema’s defining performers. The building is private, so the value lies in the precise biographical marker.', description_it='La targa ricorda le origini sud-londinesi di Charlie Chaplin, collegando una strada ordinaria alla povertà infantile e al music hall che formarono uno dei protagonisti fondamentali del cinema. L’edificio è privato: il valore sta nel preciso riferimento biografico.', editorial_hook_en='Charlie Chaplin Plaque: The plaque marks Charlie Chaplin’s South London beginnings, linking an ordinary streetscape to the childhood poverty and music-hall culture that shaped one of cinema’s defining performers.', editorial_hook_it='Charlie Chaplin Plaque: La targa ricorda le origini sud-londinesi di Charlie Chaplin, collegando una strada ordinaria alla povertà infantile e al music hall che formarono uno dei protagonisti fondamentali del cinema.', access_notes_en='Private property: view respectfully from public space and do not disturb residents or staff.', access_notes_it='Proprietà privata: osserva con rispetto dallo spazio pubblico senza disturbare residenti o personale.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.english-heritage.org.uk/visit/blue-plaques/charlie-chaplin/' WHERE id='LA-5EB28F65' AND category='ODDITY';
