UPDATE places SET description_en='A short patch of end-grain timber blocks survives beside Bunhill Fields, recalling wooden road surfaces once used to reduce wheel noise in Victorian London. The material proved slippery and difficult to maintain, which helps explain why such paving is now exceptionally rare.', description_it='Un breve tratto di blocchi di legno disposti di testa sopravvive accanto a Bunhill Fields, ricordando le pavimentazioni usate per ridurre il rumore delle ruote nella Londra vittoriana. Il materiale era scivoloso e difficile da mantenere, motivo della sua attuale rarità.', editorial_hook_en='Chequer Street Wooden Paving: A short patch of end-grain timber blocks survives beside Bunhill Fields, recalling wooden road surfaces once used to reduce wheel noise in Victorian London.', editorial_hook_it='Chequer Street Wooden Paving: Un breve tratto di blocchi di legno disposti di testa sopravvive accanto a Bunhill Fields, ricordando le pavimentazioni usate per ridurre il rumore delle ruote nella Londra vittoriana.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://livinglondonhistory.com/where-to-spot-evidence-of-londons-old-wooden-streets/' WHERE id='LA-56AB48AA' AND category='ODDITY';
