UPDATE places SET description_en='The ornamental gate on Wardour Street marks a principal entrance to London’s Chinatown. Completed in 2016 in a Qing-dynasty style by Chinese artisans, its tiled roof, painted brackets and guardian figures create a ceremonial threshold rather than merely a traffic marker.', description_it='Il portale ornamentale di Wardour Street segna uno degli ingressi principali alla Chinatown londinese. Completato nel 2016 in stile Qing da artigiani cinesi, con tetto di tegole, mensole dipinte e figure guardiane, crea una soglia cerimoniale e non un semplice segnale stradale.', editorial_hook_en='Chinatown Gate: The ornamental gate on Wardour Street marks a principal entrance to London’s Chinatown.', editorial_hook_it='Chinatown Gate: Il portale ornamentale di Wardour Street segna uno degli ingressi principali alla Chinatown londinese.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-5454FCA1' AND category='ODDITY';
