UPDATE places SET description_en='Christ Church Garden occupies the former churchyard of Christ Church Greyfriars, whose Wren church was destroyed during the Blitz. Rose beds trace the footprint of the vanished nave and a small drinking fountain survives among the planting, turning bomb damage into a legible garden plan.', description_it='Christ Church Garden occupa l’antico cimitero di Christ Church Greyfriars, chiesa di Wren distrutta durante il Blitz. Aiuole di rose seguono l’impronta della navata scomparsa e una piccola fontanella sopravvive tra le piante, trasformando i danni di guerra in una pianta leggibile.', editorial_hook_en='Christ Church Garden: Christ Church Garden occupies the former churchyard of Christ Church Greyfriars, whose Wren church was destroyed during the Blitz.', editorial_hook_it='Christ Church Garden: Christ Church Garden occupa l’antico cimitero di Christ Church Greyfriars, chiesa di Wren distrutta durante il Blitz.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-285D8952' AND category='ODDITY';
