UPDATE places SET description_en='The cast-iron dragon on a pedestal marks the western boundary of the City of London. Derived from the dragon supporters of the City’s coat of arms, these sentinels appear at major road entrances and indicate the transition into the Square Mile’s separate civic jurisdiction.', description_it='Il drago in ghisa su piedistallo segna il confine occidentale della City of London. Derivato dai draghi che sostengono lo stemma cittadino, compare agli ingressi stradali principali e indica il passaggio nella distinta giurisdizione civica dello Square Mile.', editorial_hook_en='City of London Dragon Western Boundary Mark: The cast-iron dragon on a pedestal marks the western boundary of the City of London.', editorial_hook_it='City of London Dragon Western Boundary Mark: Il drago in ghisa su piedistallo segna il confine occidentale della City of London.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-A8532503' AND category='ODDITY';
