UPDATE places SET description_en='Clattern Bridge crosses the Hogsmill in Kingston and incorporates medieval stonework dating from around the twelfth century. Still carrying road traffic, its low arches survive beside the Coronation Stone, making an unusually compact encounter with infrastructure used continuously for centuries.', description_it='Clattern Bridge attraversa l’Hogsmill a Kingston e incorpora muratura medievale risalente circa al XII secolo. Ancora percorso dal traffico, conserva archi bassi accanto alla Coronation Stone, offrendo un incontro insolitamente compatto con un’infrastruttura usata per secoli.', editorial_hook_en='Clattern Bridge: Clattern Bridge crosses the Hogsmill in Kingston and incorporates medieval stonework dating from around the twelfth century.', editorial_hook_it='Clattern Bridge: Clattern Bridge attraversa l’Hogsmill a Kingston e incorpora muratura medievale risalente circa al XII secolo.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://historicengland.org.uk/listing/the-list/list-entry/1080069' WHERE id='O12' AND category='ODDITY';
