UPDATE places SET description_en='Cleopatra’s Needle is an ancient Egyptian obelisk made for Pharaoh Thutmose III and brought to London in 1878. Victorian bronze sphinxes, bomb damage from the First World War and a time capsule buried beneath its base add later London layers to a monument far older than the city.', description_it='Cleopatra’s Needle è un obelisco egizio antico realizzato per il faraone Thutmose III e portato a Londra nel 1878. Sfingi bronzee vittoriane, danni della Prima guerra mondiale e una capsula del tempo sotto la base aggiungono strati londinesi a un monumento molto più antico della città.', editorial_hook_en='Cleopatra''s Needle: Cleopatra’s Needle is an ancient Egyptian obelisk made for Pharaoh Thutmose III and brought to London in 1878.', editorial_hook_it='Cleopatra''s Needle: Cleopatra’s Needle è un obelisco egizio antico realizzato per il faraone Thutmose III e portato a Londra nel 1878.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-59DF405C' AND category='ODDITY';
