UPDATE places SET description_en='Kingston’s Coronation Stone is traditionally associated with the crowning of several Anglo-Saxon kings. The sarsen block now stands on a purpose-built base near the Guildhall, with metal lettering naming rulers whose ceremonies helped give Kingston its royal identity.', description_it='La Coronation Stone di Kingston è tradizionalmente associata all’incoronazione di diversi re anglosassoni. Il blocco di sarsen si trova oggi su una base apposita vicino alla Guildhall, con lettere metalliche che nominano i sovrani le cui cerimonie diedero a Kingston la sua identità reale.', editorial_hook_en='Coronation Stone: Kingston’s Coronation Stone is traditionally associated with the crowning of several Anglo-Saxon kings.', editorial_hook_it='Coronation Stone: La Coronation Stone di Kingston è tradizionalmente associata all’incoronazione di diversi re anglosassoni.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-2C69C1B6' AND category='ODDITY';
