UPDATE places SET description_en='Fulham Football Club’s Craven Cottage is unusual for the red-brick pavilion and the surviving cottage tucked into a corner of the riverside stadium. Archibald Leitch’s listed stand and the intimate Thames setting preserve a scale largely lost at modern elite football grounds.', description_it='Craven Cottage del Fulham Football Club è insolito per il padiglione in mattoni rossi e il cottage superstite in un angolo dello stadio sul fiume. La tribuna tutelata di Archibald Leitch e l’intima posizione sul Tamigi conservano una scala ormai rara negli stadi moderni.', editorial_hook_en='Craven Cottage: Fulham Football Club’s Craven Cottage is unusual for the red-brick pavilion and the surviving cottage tucked into a corner of the riverside stadium.', editorial_hook_it='Craven Cottage: Craven Cottage del Fulham Football Club è insolito per il padiglione in mattoni rossi e il cottage superstite in un angolo dello stadio sul fiume.', access_notes_en='Interior access is scheduled, ticketed or event-led; check the official venue before travelling.', access_notes_it='L’accesso interno è programmato, a pagamento o legato a eventi: controlla il sito ufficiale prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.fulhamfc.com/visit/craven-cottage/' WHERE id='LA-99D6A098' AND category='ODDITY';
