UPDATE places SET description_en='Crossness Pumping Station opened in 1865 as the eastern end of Bazalgette’s sewer system. Its restored beam engines stand within exuberant cast-iron columns painted in Victorian colours, turning essential sanitation machinery into one of London’s most spectacular industrial interiors.', description_it='Crossness Pumping Station aprì nel 1865 come terminale orientale del sistema fognario di Bazalgette. Le macchine a bilanciere restaurate si trovano tra esuberanti colonne in ghisa dipinte nei colori vittoriani, trasformando l’ingegneria sanitaria in uno degli interni industriali più spettacolari di Londra.', editorial_hook_en='Crossness Pumping Station: Crossness Pumping Station opened in 1865 as the eastern end of Bazalgette’s sewer system.', editorial_hook_it='Crossness Pumping Station: Crossness Pumping Station aprì nel 1865 come terminale orientale del sistema fognario di Bazalgette.', access_notes_en='Access is seasonal or limited to selected open days; confirm the current programme before travelling.', access_notes_it='L’accesso è stagionale o limitato a giornate specifiche: verifica il programma prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://crossness.org.uk/' WHERE id='LA-F229546C' AND category='ODDITY';
