UPDATE places SET description_en='The Crystal Palace sphinxes were created in the 1850s for Joseph Paxton’s Egyptian Court after the exhibition building moved to Sydenham. They flank terraces that once introduced reconstructed ancient architecture, surviving as monumental fragments of a Victorian attempt to display world history.', description_it='Le sfingi di Crystal Palace furono create negli anni Cinquanta dell’Ottocento per l’Egyptian Court dopo il trasferimento dell’edificio espositivo a Sydenham. Fiancheggiano terrazze che introducevano ricostruzioni dell’architettura antica e sopravvivono come frammenti monumentali della visione vittoriana della storia mondiale.', editorial_hook_en='Crystal Palace Sphinxes: The Crystal Palace sphinxes were created in the 1850s for Joseph Paxton’s Egyptian Court after the exhibition building moved to Sydenham.', editorial_hook_it='Crystal Palace Sphinxes: Le sfingi di Crystal Palace furono create negli anni Cinquanta dell’Ottocento per l’Egyptian Court dopo il trasferimento dell’edificio espositivo a Sydenham.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-391AB302' AND category='ODDITY';
