UPDATE places SET description_en='The Crystal Palace Subway was built in 1865 as an ornate entrance linking the High Level railway station to the Crystal Palace. Fan-vaulted brickwork, patterned stone and Moorish-influenced details create a ceremonial underground space, now accessible through scheduled openings after restoration.', description_it='Il Crystal Palace Subway fu costruito nel 1865 come ingresso ornato tra la stazione High Level e il Crystal Palace. Volte a ventaglio in mattoni, pietra decorata e dettagli d’ispirazione moresca creano uno spazio sotterraneo cerimoniale, oggi accessibile con aperture programmate dopo il restauro.', editorial_hook_en='Crystal Palace Subway: The Crystal Palace Subway was built in 1865 as an ornate entrance linking the High Level railway station to the Crystal Palace.', editorial_hook_it='Crystal Palace Subway: Il Crystal Palace Subway fu costruito nel 1865 come ingresso ornato tra la stazione High Level e il Crystal Palace.', access_notes_en='Access is seasonal or limited to selected open days; confirm the current programme before travelling.', access_notes_it='L’accesso è stagionale o limitato a giornate specifiche: verifica il programma prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.crystalpalaceparktrust.org/pages/crystal-palace-subway' WHERE id='O15' AND category='ODDITY';
