UPDATE places SET description_en='Cutty Sark is an 1869 tea clipper preserved in dry dock at Greenwich. The ship’s copper-clad hull is suspended above a glazed visitor space, allowing the unusual experience of walking directly beneath a vessel built for speed on the China tea and Australian wool routes.', description_it='Cutty Sark è un clipper del tè del 1869 conservato in bacino a Greenwich. Lo scafo rivestito in rame è sospeso sopra uno spazio vetrato, permettendo l’insolita esperienza di camminare direttamente sotto una nave costruita per la velocità sulle rotte del tè cinese e della lana australiana.', editorial_hook_en='Cutty Sark: Cutty Sark is an 1869 tea clipper preserved in dry dock at Greenwich.', editorial_hook_it='Cutty Sark: Cutty Sark è un clipper del tè del 1869 conservato in bacino a Greenwich.', access_notes_en='Interior access is scheduled, ticketed or event-led; check the official venue before travelling.', access_notes_it='L’accesso interno è programmato, a pagamento o legato a eventi: controlla il sito ufficiale prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.rmg.co.uk/cutty-sark' WHERE id='LA-FA6E1C19' AND category='ODDITY';
