UPDATE places SET description_en='The streets around this Kennington location appear in Dexys Midnight Runners’ 1982 Come On Eileen video. Railway arches, corner shops and working-class South London architecture give the performance its recognisable setting, though individual façades and businesses have changed since filming.', description_it='Le strade attorno a questo punto di Kennington compaiono nel video Come On Eileen dei Dexys Midnight Runners del 1982. Archi ferroviari, negozi d’angolo e architettura popolare della Londra sud danno alla performance il suo scenario riconoscibile, anche se facciate e attività sono cambiate.', editorial_hook_en='Dexy''s Midnight Runners - Come On Eileen: The streets around this Kennington location appear in Dexys Midnight Runners’ 1982 Come On Eileen video.', editorial_hook_it='Dexy''s Midnight Runners - Come On Eileen: Le strade attorno a questo punto di Kennington compaiono nel video Come On Eileen dei Dexys Midnight Runners del 1982.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-88E3658D' AND category='ODDITY';
