UPDATE places SET description_en='Down Street Mews gives a surface clue to the disused Down Street Underground station below Piccadilly. Closed to passengers in 1932, the station later housed protected wartime railway operations and was used by Winston Churchill’s staff before the Cabinet War Rooms were ready.', description_it='Down Street Mews offre un indizio in superficie della stazione della metropolitana dismessa sotto Piccadilly. Chiusa ai passeggeri nel 1932, ospitò operazioni ferroviarie protette durante la guerra e fu usata dallo staff di Winston Churchill prima che le Cabinet War Rooms fossero pronte.', editorial_hook_en='Down Street Mews: Down Street Mews gives a surface clue to the disused Down Street Underground station below Piccadilly.', editorial_hook_it='Down Street Mews: Down Street Mews offre un indizio in superficie della stazione della metropolitana dismessa sotto Piccadilly.', access_notes_en='Private property: view respectfully from public space and do not disturb residents or staff.', access_notes_it='Proprietà privata: osserva con rispetto dallo spazio pubblico senza disturbare residenti o personale.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.ltmuseum.co.uk/hidden-london/down-street' WHERE id='LA-639346A3' AND category='ODDITY';
