UPDATE places SET description_en='Duck Island Cottage is a picturesque nineteenth-century lodge beside the lake in St James’s Park. Its rustic Tudor-Gothic appearance disguises a practical role connected with the park’s bird keeper and waterfowl, continuing the island’s long association with ducks and royal ornithology.', description_it='Duck Island Cottage è un pittoresco padiglione ottocentesco accanto al lago di St James’s Park. L’aspetto rustico Tudor-Gothic nasconde una funzione pratica legata al guardiano degli uccelli e agli anatidi, continuando la lunga associazione dell’isola con anatre e ornitologia reale.', editorial_hook_en='Duck Island Cottage: Duck Island Cottage is a picturesque nineteenth-century lodge beside the lake in St James’s Park.', editorial_hook_it='Duck Island Cottage: Duck Island Cottage è un pittoresco padiglione ottocentesco accanto al lago di St James’s Park.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-4532112A' AND category='ODDITY';
