UPDATE places SET description_en='The blue police box outside Earl’s Court station is a modern Metropolitan Police installation designed in the visual tradition of 1920s boxes. Its resemblance to Doctor Who’s TARDIS made it a pop-cultural landmark, although it was installed decades after the television prop’s original model.', description_it='La cabina blu della polizia fuori dalla stazione di Earl’s Court è un’installazione moderna della Metropolitan Police ispirata ai modelli degli anni Venti. La somiglianza con il TARDIS di Doctor Who l’ha resa un punto pop, benché sia stata collocata molti decenni dopo il modello del celebre oggetto televisivo.', editorial_hook_en='Earls Court Police Box: The blue police box outside Earl’s Court station is a modern Metropolitan Police installation designed in the visual tradition of 1920s boxes.', editorial_hook_it='Earls Court Police Box: La cabina blu della polizia fuori dalla stazione di Earl’s Court è un’installazione moderna della Metropolitan Police ispirata ai modelli degli anni Venti.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-F03B8F32' AND category='ODDITY';
