UPDATE places SET description_en='The Elfin Oak is the hollow trunk of an ancient oak carved by Ivor Innes in 1928–30 with tiny fairies, gnomes, animals and witches. Protected beneath a canopy near the Diana Memorial Playground, it combines natural wood forms with a densely populated miniature fantasy world.', description_it='L’Elfin Oak è il tronco cavo di un’antica quercia scolpita da Ivor Innes nel 1928–30 con minuscole fate, gnomi, animali e streghe. Protetta sotto una copertura vicino al Diana Memorial Playground, unisce le forme naturali del legno a un fitto mondo fantastico in miniatura.', editorial_hook_en='Elfin Oak: The Elfin Oak is the hollow trunk of an ancient oak carved by Ivor Innes in 1928–30 with tiny fairies, gnomes, animals and witches.', editorial_hook_it='Elfin Oak: L’Elfin Oak è il tronco cavo di un’antica quercia scolpita da Ivor Innes nel 1928–30 con minuscole fate, gnomi, animali e streghe.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.royalparks.org.uk/visit/parks/kensington-gardens/elfin-oak' WHERE id='LA-E000F10B' AND category='ODDITY';
