UPDATE places SET description_en='The green cabmen’s shelter at Embankment Place is one of the small roadside huts created from the 1870s to provide licensed cab drivers with hot food and rest without leaving their vehicles far away. Most survive as working facilities reserved for drivers.', description_it='Il rifugio verde per tassisti di Embankment Place è una delle piccole strutture stradali create dagli anni Settanta dell’Ottocento per offrire ai conducenti autorizzati cibo caldo e riposo senza allontanarsi dai veicoli. La maggior parte resta una struttura operativa riservata ai tassisti.', editorial_hook_en='Embankment Place Cabmen''s Shelter: The green cabmen’s shelter at Embankment Place is one of the small roadside huts created from the 1870s to provide licensed cab drivers with hot food and rest without leaving their vehicles far away.', editorial_hook_it='Embankment Place Cabmen''s Shelter: Il rifugio verde per tassisti di Embankment Place è una delle piccole strutture stradali create dagli anni Settanta dell’Ottocento per offrire ai conducenti autorizzati cibo caldo e riposo senza allontanarsi dai veicoli.', access_notes_en='Private property: view respectfully from public space and do not disturb residents or staff.', access_notes_it='Proprietà privata: osserva con rispetto dallo spazio pubblico senza disturbare residenti o personale.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.cabmensshelterfund.org/' WHERE id='LA-0CC14A78' AND category='ODDITY';
