UPDATE places SET description_en='The cable-car terminal at Royal Victoria Dock carries gondolas across the Thames to the Greenwich Peninsula. Formerly branded Emirates Air Line and now the IFS Cloud Cable Car, it functions as public transport and an aerial viewpoint, with towers and haul ropes forming an unusual part of East London’s skyline.', description_it='Il terminal della funivia al Royal Victoria Dock porta le cabine sopra il Tamigi fino alla Greenwich Peninsula. Già Emirates Air Line e oggi IFS Cloud Cable Car, funziona come trasporto pubblico e punto panoramico aereo, con piloni e funi diventati parte insolita dello skyline della Londra est.', editorial_hook_en='Emirates Air Line - Canning Town Station: The cable-car terminal at Royal Victoria Dock carries gondolas across the Thames to the Greenwich Peninsula.', editorial_hook_it='Emirates Air Line - Canning Town Station: Il terminal della funivia al Royal Victoria Dock porta le cabine sopra il Tamigi fino alla Greenwich Peninsula.', access_notes_en='Interior access is scheduled, ticketed or event-led; check the official venue before travelling.', access_notes_it='L’accesso interno è programmato, a pagamento o legato a eventi: controlla il sito ufficiale prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://tfl.gov.uk/modes/london-cable-car/' WHERE id='LA-DA2B6B32' AND category='ODDITY';
