UPDATE places SET description_en='The doorway at 10 Adam Street closely resembles the famous entrance to 10 Downing Street, making it a popular stand-in for photographs. Robert Adam’s eighteenth-century terrace is genuine, but this is an ordinary private address with different proportions and fittings, not a replica built as an attraction.', description_it='La porta al 10 di Adam Street assomiglia molto al celebre ingresso di 10 Downing Street ed è perciò usata come sostituto nelle fotografie. La terrazza settecentesca di Robert Adam è autentica, ma si tratta di un normale indirizzo privato con proporzioni e dettagli diversi, non di una replica turistica.', editorial_hook_en='Fake no.10: The doorway at 10 Adam Street closely resembles the famous entrance to 10 Downing Street, making it a popular stand-in for photographs.', editorial_hook_it='Fake no.10: La porta al 10 di Adam Street assomiglia molto al celebre ingresso di 10 Downing Street ed è perciò usata come sostituto nelle fotografie.', access_notes_en='Private property: view respectfully from public space and do not disturb residents or staff.', access_notes_it='Proprietà privata: osserva con rispetto dallo spazio pubblico senza disturbare residenti o personale.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.ianvisits.co.uk/articles/the-fake-10-downing-street-door-you-can-pose-in-front-of-38574/' WHERE id='O7' AND category='ODDITY';
