UPDATE places SET description_en='York Road was a Piccadilly line station between King’s Cross and Caledonian Road, open from 1906 to 1932. Street-level remnants and the tiled station building mark platforms that still lie beside operational tracks, making it a visible fragment of London’s abandoned Underground network.', description_it='York Road fu una stazione della Piccadilly line tra King’s Cross e Caledonian Road, aperta dal 1906 al 1932. Resti a livello stradale e l’edificio rivestito indicano banchine ancora accanto ai binari in uso, rendendola un frammento visibile della rete metropolitana abbandonata.', editorial_hook_en='Former York Road tube station: York Road was a Piccadilly line station between King’s Cross and Caledonian Road, open from 1906 to 1932.', editorial_hook_it='Former York Road tube station: York Road fu una stazione della Piccadilly line tra King’s Cross e Caledonian Road, aperta dal 1906 al 1932.', access_notes_en='Private property: view respectfully from public space and do not disturb residents or staff.', access_notes_it='Proprietà privata: osserva con rispetto dallo spazio pubblico senza disturbare residenti o personale.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-B7D060EF' AND category='ODDITY';
