UPDATE places SET description_en='Gentle Monster’s Selfridges concession treats eyewear retail as installation art, using kinetic sculpture, oversized figures and surreal display machinery. The changing set is part shop and part temporary spectacle, so the precise objects may differ while the deliberately uncanny approach remains.', description_it='Lo spazio Gentle Monster da Selfridges tratta la vendita di occhiali come arte installativa, usando sculture cinetiche, figure ingrandite e macchinari surreali. L’allestimento cambia ed è insieme negozio e spettacolo temporaneo: gli oggetti possono variare, ma resta l’approccio volutamente perturbante.', editorial_hook_en='Gentle Monster London Selfridges: Gentle Monster’s Selfridges concession treats eyewear retail as installation art, using kinetic sculpture, oversized figures and surreal display machinery.', editorial_hook_it='Gentle Monster London Selfridges: Lo spazio Gentle Monster da Selfridges tratta la vendita di occhiali come arte installativa, usando sculture cinetiche, figure ingrandite e macchinari surreali.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-744356F3' AND category='ODDITY';
