UPDATE places SET description_en='God’s Own Junkyard fills a Walthamstow warehouse with neon signs, film props and light works made or collected by the Bracey family. The dense glow preserves fragments of Soho, fairgrounds and screen production, with a café-bar embedded inside the working collection.', description_it='God’s Own Junkyard riempie un capannone di Walthamstow con insegne al neon, oggetti di scena e opere luminose create o raccolte dalla famiglia Bracey. Il bagliore conserva frammenti di Soho, luna park e produzioni cinematografiche, con un caffè-bar dentro la collezione attiva.', editorial_hook_en='God''s Own Junkyard: God’s Own Junkyard fills a Walthamstow warehouse with neon signs, film props and light works made or collected by the Bracey family.', editorial_hook_it='God''s Own Junkyard: God’s Own Junkyard riempie un capannone di Walthamstow con insegne al neon, oggetti di scena e opere luminose create o raccolte dalla famiglia Bracey.', access_notes_en='Interior access is scheduled, ticketed or event-led; check the official venue before travelling.', access_notes_it='L’accesso interno è programmato, a pagamento o legato a eventi: controlla il sito ufficiale prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.godsownjunkyard.co.uk/' WHERE id='O9' AND category='ODDITY';
