UPDATE places SET description_en='The north entrance of Greenwich Foot Tunnel descends by lift and spiral stairs to a cast-iron-lined pedestrian passage beneath the Thames. Opened in 1902 for dock workers, the tunnel still connects the Isle of Dogs with Greenwich, with repaired sections revealing its long battle against leaks.', description_it='L’ingresso nord del Greenwich Foot Tunnel scende con ascensore e scale a chiocciola in un passaggio pedonale rivestito di ghisa sotto il Tamigi. Aperto nel 1902 per i lavoratori dei docks, collega ancora Isle of Dogs e Greenwich; le sezioni riparate mostrano la lunga lotta contro le infiltrazioni.', editorial_hook_en='Greenwich Foot Tunnel North: The north entrance of Greenwich Foot Tunnel descends by lift and spiral stairs to a cast-iron-lined pedestrian passage beneath the Thames.', editorial_hook_it='Greenwich Foot Tunnel North: L’ingresso nord del Greenwich Foot Tunnel scende con ascensore e scale a chiocciola in un passaggio pedonale rivestito di ghisa sotto il Tamigi.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-AAEC1C99' AND category='ODDITY';
