UPDATE places SET description_en='Hammerton’s Ferry is a small passenger boat crossing between Ham House and Marble Hill, continuing a river service begun in 1908. The short trip offers a human-scale alternative to bridges, but operation depends on season, daylight, weather and river conditions.', description_it='Hammerton’s Ferry è un piccolo traghetto passeggeri tra Ham House e Marble Hill, continuazione di un servizio iniziato nel 1908. La breve traversata offre un’alternativa ai ponti su scala umana, ma dipende da stagione, luce, meteo e condizioni del fiume.', editorial_hook_en='Hammerton''s Ferry: Hammerton’s Ferry is a small passenger boat crossing between Ham House and Marble Hill, continuing a river service begun in 1908.', editorial_hook_it='Hammerton''s Ferry: Hammerton’s Ferry è un piccolo traghetto passeggeri tra Ham House e Marble Hill, continuazione di un servizio iniziato nel 1908.', access_notes_en='Access is seasonal or limited to selected open days; confirm the current programme before travelling.', access_notes_it='L’accesso è stagionale o limitato a giornate specifiche: verifica il programma prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.hammertonsferry.com/' WHERE id='LA-D05E54F5' AND category='ODDITY';
