UPDATE places SET description_en='HMS Belfast is a Second World War-era light cruiser permanently moored on the Thames. Nine decks preserve gun turrets, engine spaces, mess rooms and cramped working areas, showing the ship as a complex floating community rather than only a dramatic silhouette beside Tower Bridge.', description_it='HMS Belfast è un incrociatore leggero dell’epoca della Seconda guerra mondiale ormeggiato stabilmente sul Tamigi. Nove ponti conservano torrette, motori, mense e spazi di lavoro angusti, mostrando la nave come una complessa comunità galleggiante e non solo una sagoma accanto a Tower Bridge.', editorial_hook_en='HMS Belfast: HMS Belfast is a Second World War-era light cruiser permanently moored on the Thames.', editorial_hook_it='HMS Belfast: HMS Belfast è un incrociatore leggero dell’epoca della Seconda guerra mondiale ormeggiato stabilmente sul Tamigi.', access_notes_en='Interior access is scheduled, ticketed or event-led; check the official venue before travelling.', access_notes_it='L’accesso interno è programmato, a pagamento o legato a eventi: controlla il sito ufficiale prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.iwm.org.uk/visits/hms-belfast' WHERE id='LA-AD913BFF' AND category='ODDITY';
