UPDATE places SET description_en='Holborn Viaduct was opened in 1869 to carry a level road across the steep Fleet Valley. Its pavilions, statues and iron staircases disguise a major piece of Victorian traffic engineering, while streets and structures continue at the lower level beneath the bridge.', description_it='Holborn Viaduct aprì nel 1869 per portare una strada pianeggiante sopra la ripida valle del Fleet. Padiglioni, statue e scale in ferro celano una grande opera vittoriana di traffico, mentre strade e strutture continuano al livello inferiore sotto il ponte.', editorial_hook_en='Holborn Bridge: Holborn Viaduct was opened in 1869 to carry a level road across the steep Fleet Valley.', editorial_hook_it='Holborn Bridge: Holborn Viaduct aprì nel 1869 per portare una strada pianeggiante sopra la ripida valle del Fleet.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-A87A87EA' AND category='ODDITY';
