UPDATE places SET description_en='Horse Guards Parade is the broad ceremonial ground behind Whitehall used for Trooping the Colour and other state events. Beneath its formal surface lie traces of the former Palace of Whitehall, while changing guards, rehearsal markings and temporary structures reveal its continuing operational role.', description_it='Horse Guards Parade è il grande spazio cerimoniale dietro Whitehall usato per Trooping the Colour e altri eventi di Stato. Sotto la superficie formale restano tracce dell’antico Palace of Whitehall; cambi della guardia, segni di prova e strutture temporanee mostrano la funzione ancora operativa.', editorial_hook_en='Horse Guards Parade: Horse Guards Parade is the broad ceremonial ground behind Whitehall used for Trooping the Colour and other state events.', editorial_hook_it='Horse Guards Parade: Horse Guards Parade è il grande spazio cerimoniale dietro Whitehall usato per Trooping the Colour e altri eventi di Stato.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-FFB0F43B' AND category='ODDITY';
