UPDATE places SET description_en='Ickenham Miniature Railway carries passengers around a compact club track behind the village. Steam, diesel and electric model locomotives run on selected public days, combining precise engineering with a family ride; it is not a daily attraction.', description_it='Ickenham Miniature Railway trasporta passeggeri su un piccolo circuito del club dietro il villaggio. Locomotive in miniatura a vapore, diesel ed elettriche circolano in giornate pubbliche selezionate, unendo ingegneria precisa e gita familiare; non è un’attrazione quotidiana.', editorial_hook_en='Ickenham Miniature Railway: Ickenham Miniature Railway carries passengers around a compact club track behind the village.', editorial_hook_it='Ickenham Miniature Railway: Ickenham Miniature Railway trasporta passeggeri su un piccolo circuito del club dietro il villaggio.', access_notes_en='Access is seasonal or limited to selected open days; confirm the current programme before travelling.', access_notes_it='L’accesso è stagionale o limitato a giornate specifiche: verifica il programma prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-BCEBA53F' AND category='ODDITY';
