UPDATE places SET description_en='University College London displays philosopher Jeremy Bentham’s preserved ‘Auto-Icon’: his clothed skeleton seated in a cabinet, with a wax head replacing the unsuccessfully preserved original. The display embodies Bentham’s utilitarian wish to remain useful after death and is now housed in UCL’s student centre.', description_it='University College London espone l’“Auto-Icon” del filosofo Jeremy Bentham: lo scheletro vestito seduto in una vetrina, con una testa di cera al posto dell’originale mal conservata. L’installazione realizza il desiderio utilitarista di Bentham di restare utile dopo la morte ed è oggi nello student centre UCL.', editorial_hook_en='Jeremy Bentham Room (JBR): University College London displays philosopher Jeremy Bentham’s preserved ‘Auto-Icon’: his clothed skeleton seated in a cabinet, with a wax head replacing the unsuccessfully preserved original.', editorial_hook_it='Jeremy Bentham Room (JBR): University College London espone l’“Auto-Icon” del filosofo Jeremy Bentham: lo scheletro vestito seduto in una vetrina, con una testa di cera al posto dell’originale mal conservata.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.ucl.ac.uk/bentham-project/about-jeremy-bentham/auto-icon' WHERE id='LA-97517C85' AND category='ODDITY';
