UPDATE places SET description_en='Leadenhall Market occupies a richly painted iron-and-glass arcade designed by Horace Jones in the nineteenth century on a market site of much older origin. Its narrow passages conceal shops and restaurants, while the ornate roof has made it a recurring film location.', description_it='Leadenhall Market occupa una galleria in ferro e vetro riccamente dipinta progettata da Horace Jones nell’Ottocento su un sito mercatale molto più antico. I passaggi stretti ospitano negozi e ristoranti, mentre il tetto ornato ne ha fatto una frequente location cinematografica.', editorial_hook_en='Leadenhall Market: Leadenhall Market occupies a richly painted iron-and-glass arcade designed by Horace Jones in the nineteenth century on a market site of much older origin.', editorial_hook_it='Leadenhall Market: Leadenhall Market occupa una galleria in ferro e vetro riccamente dipinta progettata da Horace Jones nell’Ottocento su un sito mercatale molto più antico.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-B00C7D7D' AND category='ODDITY';
