UPDATE places SET description_en='Leinster Gardens hides false façades at numbers 23–24, built in the 1860s to conceal an open section of the Underground railway. Painted windows and blank doors continue the rhythm of the neighbouring terrace while ventilation and tracks occupy the space behind.', description_it='Leinster Gardens nasconde false facciate ai numeri 23–24, costruite negli anni Sessanta dell’Ottocento per celare un tratto aperto della metropolitana. Finestre dipinte e porte cieche continuano il ritmo delle case vicine, mentre dietro si trovano ventilazione e binari.', editorial_hook_en='Leinster Gardens False Facades: Leinster Gardens hides false façades at numbers 23–24, built in the 1860s to conceal an open section of the Underground railway.', editorial_hook_it='Leinster Gardens False Facades: Leinster Gardens nasconde false facciate ai numeri 23–24, costruite negli anni Sessanta dell’Ottocento per celare un tratto aperto della metropolitana.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://historicengland.org.uk/listing/the-list/list-entry/1221942' WHERE id='O8' AND category='ODDITY';
