UPDATE places SET description_en='The present London Bridge is a restrained concrete crossing opened in 1973, replacing the nineteenth-century bridge sold and reconstructed in Arizona. Its apparent ordinariness masks a site where successive bridges have channelled London’s movement and commerce for nearly two millennia.', description_it='L’attuale London Bridge è un sobrio ponte in cemento aperto nel 1973, sostituto del ponte ottocentesco venduto e ricostruito in Arizona. L’apparente normalità nasconde un luogo dove ponti successivi hanno incanalato movimento e commercio londinese per quasi due millenni.', editorial_hook_en='London Bridge: The present London Bridge is a restrained concrete crossing opened in 1973, replacing the nineteenth-century bridge sold and reconstructed in Arizona.', editorial_hook_it='London Bridge: L’attuale London Bridge è un sobrio ponte in cemento aperto nel 1973, sostituto del ponte ottocentesco venduto e ricostruito in Arizona.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-2BF2F4FF' AND category='ODDITY';
