UPDATE places SET description_en='The London Eye is a 135-metre observation wheel built for the millennium, with passenger capsules mounted outside the rim to preserve uninterrupted views. Its slow continuous rotation normally allows boarding without stopping, turning engineering mechanics into a thirty-minute moving panorama.', description_it='Il London Eye è una ruota panoramica di 135 metri costruita per il millennio, con capsule montate all’esterno del cerchio per mantenere la vista libera. La lenta rotazione continua consente normalmente l’imbarco senza fermarsi, trasformando la meccanica in un panorama mobile di trenta minuti.', editorial_hook_en='London Eye: The London Eye is a 135-metre observation wheel built for the millennium, with passenger capsules mounted outside the rim to preserve uninterrupted views.', editorial_hook_it='London Eye: Il London Eye è una ruota panoramica di 135 metri costruita per il millennio, con capsule montate all’esterno del cerchio per mantenere la vista libera.', access_notes_en='Interior access is scheduled, ticketed or event-led; check the official venue before travelling.', access_notes_it='L’accesso interno è programmato, a pagamento o legato a eventi: controlla il sito ufficiale prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.londoneye.com/' WHERE id='LA-78266B44' AND category='ODDITY';
