UPDATE places SET description_en='The London Stone is a small block of limestone with a remarkably large mythology. Recorded for centuries on Cannon Street, it has been claimed as a Roman milestone, civic talisman and object of legend; the surviving fragment is displayed behind protective glass.', description_it='La London Stone è un piccolo blocco di calcare circondato da una mitologia sorprendentemente vasta. Documentata per secoli in Cannon Street, è stata interpretata come pietra miliare romana, talismano civico e oggetto leggendario; il frammento superstite è esposto dietro un vetro protettivo.', editorial_hook_en='London Stone (remaining part): The London Stone is a small block of limestone with a remarkably large mythology.', editorial_hook_it='London Stone (remaining part): La London Stone è un piccolo blocco di calcare circondato da una mitologia sorprendentemente vasta.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-4E9238B2' AND category='ODDITY';
