UPDATE places SET description_en='This exposed section of London’s defensive wall contains Roman masonry at its base and medieval rebuilding above. Standing beside later roads and towers, it makes the changing height, materials and repeated reuse of the city boundary legible at close range.', description_it='Questo tratto esposto delle mura difensive di Londra contiene muratura romana alla base e ricostruzioni medievali sopra. Accanto a strade e torri successive, rende leggibili da vicino variazioni d’altezza, materiali e ripetuti riusi del confine cittadino.', editorial_hook_en='London Wall: This exposed section of London’s defensive wall contains Roman masonry at its base and medieval rebuilding above.', editorial_hook_it='London Wall: Questo tratto esposto delle mura difensive di Londra contiene muratura romana alla base e ricostruzioni medievali sopra.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-AD25F437' AND category='ODDITY';
