UPDATE places SET description_en='These exceptionally tall doors in Covent Garden exaggerate the proportions of an otherwise conventional façade. Their elongated panels likely respond to former commercial loading or theatrical use, creating a visual puzzle best understood by comparing them with the smaller surrounding openings.', description_it='Queste porte eccezionalmente alte a Covent Garden esasperano le proporzioni di una facciata altrimenti normale. I pannelli allungati probabilmente rispondono a precedenti usi commerciali o teatrali, creando un enigma visivo da confrontare con le aperture più piccole circostanti.', editorial_hook_en='Long doors: These exceptionally tall doors in Covent Garden exaggerate the proportions of an otherwise conventional façade.', editorial_hook_it='Long doors: Queste porte eccezionalmente alte a Covent Garden esasperano le proporzioni di una facciata altrimenti normale.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-812D6CBF' AND category='ODDITY';
