UPDATE places SET description_en='Lower Robert Street is a dark service road beneath the raised Strand and Adelphi development. Concrete spans, ventilation noise and little daylight create an unusually cinematic undercroft, while rumours and ghost stories reflect how infrastructure hidden below prestigious streets acquires its own folklore.', description_it='Lower Robert Street è una buia strada di servizio sotto lo Strand sopraelevato e lo sviluppo Adelphi. Campate in cemento, rumore della ventilazione e poca luce creano un sottosuolo cinematografico; voci e storie di fantasmi mostrano come l’infrastruttura nascosta sotto vie prestigiose generi un proprio folklore.', editorial_hook_en='Lower Robert st: Lower Robert Street is a dark service road beneath the raised Strand and Adelphi development.', editorial_hook_it='Lower Robert st: Lower Robert Street è una buia strada di servizio sotto lo Strand sopraelevato e lo sviluppo Adelphi.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-930FC848' AND category='ODDITY';
