UPDATE places SET description_en='The chapter house foundations of medieval Merton Priory survive beneath the road and retail development near Colliers Wood. Interpretation reconstructs the scale of the Augustinian complex where Thomas Becket studied and where major medieval councils met, making archaeology visible in an unlikely modern setting.', description_it='Le fondamenta della sala capitolare del medievale Merton Priory sopravvivono sotto la strada e lo sviluppo commerciale vicino a Colliers Wood. L’allestimento ricostruisce il complesso agostiniano dove studiò Thomas Becket e si tennero importanti concili, rendendo visibile l’archeologia in un ambiente moderno inatteso.', editorial_hook_en='Merton Priory Chapter House: The chapter house foundations of medieval Merton Priory survive beneath the road and retail development near Colliers Wood.', editorial_hook_it='Merton Priory Chapter House: Le fondamenta della sala capitolare del medievale Merton Priory sopravvivono sotto la strada e lo sviluppo commerciale vicino a Colliers Wood.', access_notes_en='Access is seasonal or limited to selected open days; confirm the current programme before travelling.', access_notes_it='L’accesso è stagionale o limitato a giornate specifiche: verifica il programma prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.mertonpriory.org/' WHERE id='LA-EE7C55A5' AND category='ODDITY';
