UPDATE places SET description_en='The grave of Paddington Bear creator Michael Bond stands in Paddington Old Cemetery. Its restrained headstone includes an affectionate reference to the courteous bear he gave the world, creating a quiet literary memorial rather than a themed attraction.', description_it='La tomba di Michael Bond, creatore dell’orso Paddington, si trova nel Paddington Old Cemetery. La sobria lapide include un affettuoso richiamo all’educato orsetto donato al mondo, creando un tranquillo memoriale letterario e non un’attrazione tematica.', editorial_hook_en='Michael Bond Grave: The grave of Paddington Bear creator Michael Bond stands in Paddington Old Cemetery.', editorial_hook_it='Michael Bond Grave: La tomba di Michael Bond, creatore dell’orso Paddington, si trova nel Paddington Old Cemetery.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.brent.gov.uk/births-deaths-marriages-nationality/deaths-and-funeral-services/brent-cemeteries/paddington-old-cemetery' WHERE id='LA-4B936C51' AND category='ODDITY';
