UPDATE places SET description_en='The Millennium Maze is a large pavement labyrinth in Northala Fields, set among the park’s conspicuous man-made hills. Its single winding route is designed for walking rather than getting lost, turning a traditional contemplative pattern into a piece of public landscape.', description_it='Il Millennium Maze è un grande labirinto pavimentato a Northala Fields, tra le evidenti colline artificiali del parco. Il percorso unico e sinuoso è pensato per camminare, non per perdersi, trasformando un motivo contemplativo tradizionale in paesaggio pubblico.', editorial_hook_en='Millennium Maze: The Millennium Maze is a large pavement labyrinth in Northala Fields, set among the park’s conspicuous man-made hills.', editorial_hook_it='Millennium Maze: Il Millennium Maze è un grande labirinto pavimentato a Northala Fields, tra le evidenti colline artificiali del parco.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-E7E3D284' AND category='ODDITY';
