UPDATE places SET description_en='A mature mimosa brings feathery foliage and bright winter blossom to this Pimlico streetscape. The tree is notable because its Mediterranean appearance contrasts with London’s climate and formal terraces; flowering varies with weather and should not be assumed year-round.', description_it='Una mimosa adulta porta foglie leggere e vivace fioritura invernale in questa strada di Pimlico. L’albero è notevole perché l’aspetto mediterraneo contrasta con il clima londinese e le terrazze formali; la fioritura dipende dal meteo e non è presente tutto l’anno.', editorial_hook_en='Mimosa tree: A mature mimosa brings feathery foliage and bright winter blossom to this Pimlico streetscape.', editorial_hook_it='Mimosa tree: Una mimosa adulta porta foglie leggere e vivace fioritura invernale in questa strada di Pimlico.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-B427F6B9' AND category='ODDITY';
