UPDATE places SET description_en='Mission: Breakout occupies part of the former South Kentish Town Underground station, closed to passengers in 1924. Escape-room games use the tiled passages and transport history of the disused station, providing rare commercial access to infrastructure otherwise hidden from the street.', description_it='Mission: Breakout occupa parte dell’ex stazione della metropolitana South Kentish Town, chiusa ai passeggeri nel 1924. Le escape room sfruttano passaggi piastrellati e storia dei trasporti, offrendo un raro accesso commerciale a infrastrutture altrimenti nascoste dalla strada.', editorial_hook_en='MISSION: BREAKOUT: Mission: Breakout occupies part of the former South Kentish Town Underground station, closed to passengers in 1924.', editorial_hook_it='MISSION: BREAKOUT: Mission: Breakout occupa parte dell’ex stazione della metropolitana South Kentish Town, chiusa ai passeggeri nel 1924.', access_notes_en='Interior access is scheduled, ticketed or event-led; check the official venue before travelling.', access_notes_it='L’accesso interno è programmato, a pagamento o legato a eventi: controlla il sito ufficiale prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://missionbreakout.london/' WHERE id='LA-2E04D304' AND category='ODDITY';
