UPDATE places SET description_en='John Reardon’s 2009 painted-bronze cockatoo lies theatrically on its plinth in Greenwich. The absurd memorial is inevitably associated with Monty Python’s dead-parrot sketch, turning the solemn language of public monuments into a compact visual joke.', description_it='Il cacatua in bronzo dipinto creato da John Reardon nel 2009 giace teatralmente sul piedistallo a Greenwich. L’assurdo memoriale richiama inevitabilmente lo sketch del pappagallo morto dei Monty Python, trasformando il linguaggio solenne dei monumenti pubblici in una battuta visiva.', editorial_hook_en='Monument for a Dead Parrot: John Reardon’s 2009 painted-bronze cockatoo lies theatrically on its plinth in Greenwich.', editorial_hook_it='Monument for a Dead Parrot: Il cacatua in bronzo dipinto creato da John Reardon nel 2009 giace teatralmente sul piedistallo a Greenwich.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://artuk.org/discover/artworks/monument-for-a-dead-parrot-273051' WHERE id='LA-4F0DBF14' AND category='ODDITY';
