UPDATE places SET description_en='The Monument to the Unknown Artist presents a life-size figure apparently drawing or measuring the riverside scene. By commemorating an unnamed creative worker rather than a famous individual, the sculpture playfully questions who receives public recognition.', description_it='Il Monument to the Unknown Artist presenta una figura a grandezza naturale intenta apparentemente a disegnare o misurare il paesaggio fluviale. Celebrando un lavoratore creativo senza nome invece di una personalità famosa, la scultura interroga con ironia chi riceve riconoscimento pubblico.', editorial_hook_en='Monument to the Unknown Artist: The Monument to the Unknown Artist presents a life-size figure apparently drawing or measuring the riverside scene.', editorial_hook_it='Monument to the Unknown Artist: Il Monument to the Unknown Artist presenta una figura a grandezza naturale intenta apparentemente a disegnare o misurare il paesaggio fluviale.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-7B219F2A' AND category='ODDITY';
