UPDATE places SET description_en='The National Covid Memorial Wall carries tens of thousands of hand-painted red hearts along the Thames opposite Parliament. Created by bereaved families and volunteers, each heart represents a life lost, making the wall both an evolving grassroots memorial and a public demand for remembrance.', description_it='Il National Covid Memorial Wall porta decine di migliaia di cuori rossi dipinti a mano lungo il Tamigi di fronte al Parlamento. Creato da familiari e volontari, ogni cuore rappresenta una vita perduta, rendendo il muro insieme memoriale popolare in evoluzione e richiesta pubblica di memoria.', editorial_hook_en='National Covid Memorial Wall: The National Covid Memorial Wall carries tens of thousands of hand-painted red hearts along the Thames opposite Parliament.', editorial_hook_it='National Covid Memorial Wall: Il National Covid Memorial Wall porta decine di migliaia di cuori rossi dipinti a mano lungo il Tamigi di fronte al Parlamento.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://nationalcovidmemorialwall.org/' WHERE id='LA-23527BAF' AND category='ODDITY';
