UPDATE places SET description_en='The so-called Roman Bath in Strand Lane is probably a seventeenth-century cistern associated with the former Arundel House water system, not an ancient Roman bathing pool. Later romantic promotion created the misleading name; the small chamber is viewed through a window or by arranged access.', description_it='Il cosiddetto Roman Bath di Strand Lane è probabilmente una cisterna seicentesca legata al sistema idrico di Arundel House, non una vasca romana antica. La promozione romantica successiva generò il nome fuorviante; la piccola camera si osserva da una finestra o con accesso concordato.', editorial_hook_en='National Trust - Strand Lane "Roman Bath": The so-called Roman Bath in Strand Lane is probably a seventeenth-century cistern associated with the former Arundel House water system, not an ancient Roman bathing pool.', editorial_hook_it='National Trust - Strand Lane "Roman Bath": Il cosiddetto Roman Bath di Strand Lane è probabilmente una cisterna seicentesca legata al sistema idrico di Arundel House, non una vasca romana antica.', access_notes_en='Public access is limited or arrangement-dependent; confirm current conditions before travelling.', access_notes_it='L’accesso pubblico è limitato o dipende da accordi specifici: verifica le condizioni prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.nationaltrust.org.uk/visit/london/strand-lane-roman-bath' WHERE id='LA-603558FF' AND category='ODDITY';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://www.nationaltrust.org.uk/visit/london/strand-lane-roman-bath','official-or-authoritative','2026-10-28' FROM places WHERE id='LA-603558FF' ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='Neal’s Yard is a small Covent Garden courtyard whose brightly painted façades conceal cafés, wellness businesses and upper-level passages. Formerly a service yard, it was reshaped by alternative entrepreneur Nicholas Saunders and became a compact example of late twentieth-century urban reinvention.', description_it='Neal’s Yard è un piccolo cortile di Covent Garden con facciate vivacemente dipinte che nascondono caffè, attività di benessere e passaggi ai piani superiori. Antico cortile di servizio, fu trasformato dall’imprenditore alternativo Nicholas Saunders in un esempio compatto di reinvenzione urbana tardo-novecentesca.', editorial_hook_en='Neals Yard: Neal’s Yard is a small Covent Garden courtyard whose brightly painted façades conceal cafés, wellness businesses and upper-level passages.', editorial_hook_it='Neals Yard: Neal’s Yard è un piccolo cortile di Covent Garden con facciate vivacemente dipinte che nascondono caffè, attività di benessere e passaggi ai piani superiori.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-01272201' AND category='ODDITY';
