UPDATE places SET description_en='The surviving façade at 121 Westminster Bridge Road belonged to the second London Necropolis station, opened in 1902. Special trains carried coffins and mourners to Brookwood Cemetery, separating classes and faiths in a unique railway system largely destroyed during the Blitz.', description_it='La facciata superstite al 121 di Westminster Bridge Road apparteneva alla seconda stazione della London Necropolis Railway, aperta nel 1902. Treni speciali portavano bare e persone in lutto al Brookwood Cemetery, separando classi e confessioni in un sistema unico, in gran parte distrutto nel Blitz.', editorial_hook_en='Necropolis station: The surviving façade at 121 Westminster Bridge Road belonged to the second London Necropolis station, opened in 1902.', editorial_hook_it='Necropolis station: La facciata superstite al 121 di Westminster Bridge Road apparteneva alla seconda stazione della London Necropolis Railway, aperta nel 1902.', access_notes_en='Private property: view respectfully from public space and do not disturb residents or staff.', access_notes_it='Proprietà privata: osserva con rispetto dallo spazio pubblico senza disturbare residenti o personale.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='O11' AND category='ODDITY';
