UPDATE places SET description_en='The façades around New Inn Yard form a changing Shoreditch street-art canvas, with large commissions and smaller interventions wrapping brick walls above active studios and businesses. The work is temporary by nature, so changes are part of the site rather than damage to a fixed display.', description_it='Le facciate attorno a New Inn Yard formano una tela mutevole della street art di Shoreditch, con grandi commissioni e interventi minori sui muri in mattoni sopra studi e attività operative. Le opere sono temporanee per natura: i cambiamenti fanno parte del luogo e non sono danni a un’esposizione fissa.', editorial_hook_en='New Inn Yard Graffiti Building: The façades around New Inn Yard form a changing Shoreditch street-art canvas, with large commissions and smaller interventions wrapping brick walls above active studios and businesses.', editorial_hook_it='New Inn Yard Graffiti Building: Le facciate attorno a New Inn Yard formano una tela mutevole della street art di Shoreditch, con grandi commissioni e interventi minori sui muri in mattoni sopra studi e attività operative.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-9C627353' AND category='ODDITY';
