UPDATE places SET description_en='Novelty Automation is artist Tim Hunkin’s arcade of hand-built satirical machines. Visitors operate coin-fed contraptions about bureaucracy, fame, money and everyday anxieties, reviving the seaside amusement arcade as mechanical theatre with an eccentric contemporary intelligence.', description_it='Novelty Automation è la sala giochi di macchine satiriche costruite a mano dall’artista Tim Hunkin. I visitatori azionano con monete congegni su burocrazia, fama, denaro e ansie quotidiane, reinventando la sala giochi balneare come teatro meccanico dall’intelligenza contemporanea ed eccentrica.', editorial_hook_en='Novelty Automation: Novelty Automation is artist Tim Hunkin’s arcade of hand-built satirical machines.', editorial_hook_it='Novelty Automation: Novelty Automation è la sala giochi di macchine satiriche costruite a mano dall’artista Tim Hunkin.', access_notes_en='Interior access is scheduled, ticketed or event-led; check the official venue before travelling.', access_notes_it='L’accesso interno è programmato, a pagamento o legato a eventi: controlla il sito ufficiale prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.novelty-automation.com/' WHERE id='LA-83CD1CDE' AND category='ODDITY';
