UPDATE places SET description_en='The Ouse Valley Viaduct carries the London–Brighton railway across the Sussex countryside on thirty-seven tall brick arches. Looking through the repeated piers creates a famously hypnotic perspective, but the structure lies outside London and must be approached using public paths without entering the railway.', description_it='L’Ouse Valley Viaduct porta la ferrovia Londra–Brighton attraverso la campagna del Sussex su trentasette alti archi in mattoni. Guardare lungo i pilastri ripetuti crea una celebre prospettiva ipnotica, ma la struttura è fuori Londra e va raggiunta da sentieri pubblici senza entrare nella ferrovia.', editorial_hook_en='Ouse Valley Viaduct: The Ouse Valley Viaduct carries the London–Brighton railway across the Sussex countryside on thirty-seven tall brick arches.', editorial_hook_it='Ouse Valley Viaduct: L’Ouse Valley Viaduct porta la ferrovia Londra–Brighton attraverso la campagna del Sussex su trentasette alti archi in mattoni.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-E9371F5E' AND category='ODDITY';
