UPDATE places SET description_en='The Painted Hall at the Old Royal Naval College covers its walls and ceiling with Sir James Thornhill’s vast Baroque scheme celebrating monarchy, maritime power and the Protestant succession. Perspective tricks and allegorical figures earned it the nickname ‘Britain’s Sistine Chapel’.', description_it='La Painted Hall dell’Old Royal Naval College copre pareti e soffitto con il vasto ciclo barocco di Sir James Thornhill, celebrazione di monarchia, potere marittimo e successione protestante. Prospettive illusionistiche e figure allegoriche le valsero il soprannome di “Cappella Sistina britannica”.', editorial_hook_en='Painted Hall: The Painted Hall at the Old Royal Naval College covers its walls and ceiling with Sir James Thornhill’s vast Baroque scheme celebrating monarchy, maritime power and the Protestant succession.', editorial_hook_it='Painted Hall: La Painted Hall dell’Old Royal Naval College copre pareti e soffitto con il vasto ciclo barocco di Sir James Thornhill, celebrazione di monarchia, potere marittimo e successione protestante.', access_notes_en='Interior access is scheduled, ticketed or event-led; check the official venue before travelling.', access_notes_it='L’accesso interno è programmato, a pagamento o legato a eventi: controlla il sito ufficiale prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://ornc.org/explore-whats-here/painted-hall/' WHERE id='LA-70FCEB5B' AND category='ODDITY';
