UPDATE places SET description_en='The golden figure of St Paul placed near the cathedral presents the apostle as a compact contemporary landmark against Wren’s much larger architecture. Its reflective surface and elevated position make the sculpture change dramatically with weather, light and viewing angle.', description_it='La figura dorata di San Paolo vicino alla cattedrale presenta l’apostolo come un compatto segno contemporaneo contro la molto più grande architettura di Wren. Superficie riflettente e posizione elevata fanno cambiare radicalmente la scultura con meteo, luce e angolo di osservazione.', editorial_hook_en='Phoenix St Paul: The golden figure of St Paul placed near the cathedral presents the apostle as a compact contemporary landmark against Wren’s much larger architecture.', editorial_hook_it='Phoenix St Paul: La figura dorata di San Paolo vicino alla cattedrale presenta l’apostolo come un compatto segno contemporaneo contro la molto più grande architettura di Wren.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-707649ED' AND category='ODDITY';
