UPDATE places SET description_en='The Diana Memorial Fountain is a loop of Cornish granite through which water flows in contrasting smooth and turbulent channels. Visitors can approach and touch the water, making the memorial an inhabitable landscape rather than a conventional statue, though access changes in poor weather.', description_it='La Diana Memorial Fountain è un anello di granito della Cornovaglia attraversato da acqua in canali alternativamente lisci e turbolenti. I visitatori possono avvicinarsi e toccarla, rendendo il memoriale un paesaggio abitabile invece di una statua convenzionale; l’accesso varia con il maltempo.', editorial_hook_en='Princess Diana Memorial Fountain: The Diana Memorial Fountain is a loop of Cornish granite through which water flows in contrasting smooth and turbulent channels.', editorial_hook_it='Princess Diana Memorial Fountain: La Diana Memorial Fountain è un anello di granito della Cornovaglia attraversato da acqua in canali alternativamente lisci e turbolenti.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-68F22428' AND category='ODDITY';
