UPDATE places SET description_en='This Earl’s Court flat was Diana Spencer’s home before her marriage to Prince Charles. The building is private, and its interest lies in the contrast between an ordinary shared London address and the intensely public royal life that followed.', description_it='Questo appartamento di Earl’s Court fu la casa di Diana Spencer prima del matrimonio con il principe Carlo. L’edificio è privato e l’interesse sta nel contrasto tra un normale indirizzo londinese condiviso e la vita reale intensamente pubblica che seguì.', editorial_hook_en='Princess Diana''s Flat: This Earl’s Court flat was Diana Spencer’s home before her marriage to Prince Charles.', editorial_hook_it='Princess Diana''s Flat: Questo appartamento di Earl’s Court fu la casa di Diana Spencer prima del matrimonio con il principe Carlo.', access_notes_en='Private property: view respectfully from public space and do not disturb residents or staff.', access_notes_it='Proprietà privata: osserva con rispetto dallo spazio pubblico senza disturbare residenti o personale.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-A727721E' AND category='ODDITY';
