UPDATE places SET description_en='Queen Caroline’s Bath is a surviving fragment of the demolished Montagu House in Greenwich Park. Despite the name, the sunken brick-and-stone structure may have served as a plunge pool or garden feature; its incomplete evidence makes the uncertainty part of the attraction.', description_it='Queen Caroline’s Bath è un frammento superstite della demolita Montagu House a Greenwich Park. Nonostante il nome, la struttura incassata in mattoni e pietra potrebbe essere stata una vasca o un elemento del giardino; l’incertezza delle prove fa parte del suo interesse.', editorial_hook_en='Queen Caroline''s Bath: Queen Caroline’s Bath is a surviving fragment of the demolished Montagu House in Greenwich Park.', editorial_hook_it='Queen Caroline''s Bath: Queen Caroline’s Bath è un frammento superstite della demolita Montagu House a Greenwich Park.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-E4CC6310' AND category='ODDITY';
