UPDATE places SET description_en='The hollow veteran oak in Greenwich Park is traditionally associated with Queen Elizabeth I, though the precise royal stories are difficult to verify. Its immense decayed trunk is valuable as both living habitat and a focus for layers of park folklore.', description_it='La grande quercia cava di Greenwich Park è tradizionalmente associata a Elisabetta I, anche se le storie reali precise sono difficili da verificare. L’enorme tronco in decomposizione ha valore sia come habitat vivente sia come centro di stratificazioni folkloriche del parco.', editorial_hook_en='Queen Elizabeth I Oak: The hollow veteran oak in Greenwich Park is traditionally associated with Queen Elizabeth I, though the precise royal stories are difficult to verify.', editorial_hook_it='Queen Elizabeth I Oak: La grande quercia cava di Greenwich Park è tradizionalmente associata a Elisabetta I, anche se le storie reali precise sono difficili da verificare.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-0FC22A54' AND category='ODDITY';
