UPDATE places SET description_en='The River Crane shot tower is a tall brick remnant of the former gunpowder and metalworking landscape of west London. Molten lead was once dropped through towers to form spherical shot as it cooled; the surviving structure now stands among riverside greenery.', description_it='La shot tower del River Crane è un alto residuo in mattoni dell’antico paesaggio di polverifici e lavorazione dei metalli della Londra ovest. Il piombo fuso veniva lasciato cadere nelle torri per formare pallini sferici raffreddandosi; la struttura oggi emerge tra il verde fluviale.', editorial_hook_en='River Crane Brick (Shot) Tower: The River Crane shot tower is a tall brick remnant of the former gunpowder and metalworking landscape of west London.', editorial_hook_it='River Crane Brick (Shot) Tower: La shot tower del River Crane è un alto residuo in mattoni dell’antico paesaggio di polverifici e lavorazione dei metalli della Londra ovest.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-0BB04092' AND category='ODDITY';
