UPDATE places SET description_en='This Holland Park property is associated with entertainer Robbie Williams, but it remains a private residence rather than a visitor site. Its mapped interest is celebrity geography only; observe the street architecture without photographing occupants or lingering at entrances.', description_it='Questa proprietà di Holland Park è associata all’artista Robbie Williams, ma resta un’abitazione privata e non un luogo visitabile. L’interesse cartografico riguarda soltanto la geografia delle celebrità: osserva l’architettura della strada senza fotografare residenti o sostare agli ingressi.', editorial_hook_en='Robbie Williams House: This Holland Park property is associated with entertainer Robbie Williams, but it remains a private residence rather than a visitor site.', editorial_hook_it='Robbie Williams House: Questa proprietà di Holland Park è associata all’artista Robbie Williams, ma resta un’abitazione privata e non un luogo visitabile.', access_notes_en='Private property: view respectfully from public space and do not disturb residents or staff.', access_notes_it='Proprietà privata: osserva con rispetto dallo spazio pubblico senza disturbare residenti o personale.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-BC372D13' AND category='ODDITY';
