UPDATE places SET description_en='The reconstructed west gate of London’s Roman fort is marked in the streets and structures near the Museum of London site. Foundations reveal how the military enclosure preceded and was later absorbed into the wider city wall.', description_it='La porta occidentale ricostruita del forte romano di Londra è segnalata nelle strade e strutture vicino all’ex Museum of London. Le fondazioni mostrano come il recinto militare precedette e fu poi incorporato nelle mura cittadine più ampie.', editorial_hook_en='Roman Fort Gate: The reconstructed west gate of London’s Roman fort is marked in the streets and structures near the Museum of London site.', editorial_hook_it='Roman Fort Gate: La porta occidentale ricostruita del forte romano di Londra è segnalata nelle strade e strutture vicino all’ex Museum of London.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-37A6BE5B' AND category='ODDITY';
