UPDATE places SET description_en='Ruislip Lido Railway is a twelve-inch-gauge miniature railway running through woodland beside the reservoir and beach. Volunteer-operated trains connect two stations on selected days, making the journey itself a compact piece of working leisure engineering.', description_it='Ruislip Lido Railway è una ferrovia in miniatura a scartamento di dodici pollici che attraversa il bosco accanto al bacino e alla spiaggia. Treni gestiti da volontari collegano due stazioni in giorni selezionati, trasformando il viaggio in un piccolo esempio di ingegneria ricreativa funzionante.', editorial_hook_en='Ruislip Lido Railway: Ruislip Lido Railway is a twelve-inch-gauge miniature railway running through woodland beside the reservoir and beach.', editorial_hook_it='Ruislip Lido Railway: Ruislip Lido Railway è una ferrovia in miniatura a scartamento di dodici pollici che attraversa il bosco accanto al bacino e alla spiaggia.', access_notes_en='Access is seasonal or limited to selected open days; confirm the current programme before travelling.', access_notes_it='L’accesso è stagionale o limitato a giornate specifiche: verifica il programma prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.ruisliplidorailway.org/' WHERE id='LA-35BA0210' AND category='ODDITY';
