UPDATE places SET description_en='Russell Square’s green cabmen’s shelter is one of the surviving huts founded from the 1870s to provide licensed cab drivers with food and rest. It remains a working facility for drivers, so admire the compact timber design without treating it as a public café.', description_it='Il rifugio verde per tassisti di Russell Square è una delle strutture superstiti create dagli anni Settanta dell’Ottocento per offrire cibo e riposo ai conducenti autorizzati. Resta un servizio operativo riservato: osserva il piccolo edificio in legno senza considerarlo un caffè pubblico.', editorial_hook_en='Russell Square Cabmen''s Shelter: Russell Square’s green cabmen’s shelter is one of the surviving huts founded from the 1870s to provide licensed cab drivers with food and rest.', editorial_hook_it='Russell Square Cabmen''s Shelter: Il rifugio verde per tassisti di Russell Square è una delle strutture superstiti create dagli anni Settanta dell’Ottocento per offrire cibo e riposo ai conducenti autorizzati.', access_notes_en='Private property: view respectfully from public space and do not disturb residents or staff.', access_notes_it='Proprietà privata: osserva con rispetto dallo spazio pubblico senza disturbare residenti o personale.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.cabmensshelterfund.org/' WHERE id='LA-303DB9AB' AND category='ODDITY';
