UPDATE places SET description_en='The large aquarium inside Salesforce Tower brings a living aquatic display into a corporate office lobby. Visibility and access depend on building security and current tenant arrangements, so it should not be assumed to be an unrestricted public attraction.', description_it='Il grande acquario dentro Salesforce Tower porta un ambiente acquatico vivente nell’atrio di un edificio aziendale. Visibilità e accesso dipendono dalla sicurezza e dagli accordi degli occupanti, quindi non va considerato un’attrazione pubblica liberamente accessibile.', editorial_hook_en='Salesforce Tower - Fish tank: The large aquarium inside Salesforce Tower brings a living aquatic display into a corporate office lobby.', editorial_hook_it='Salesforce Tower - Fish tank: Il grande acquario dentro Salesforce Tower porta un ambiente acquatico vivente nell’atrio di un edificio aziendale.', access_notes_en='Private property: view respectfully from public space and do not disturb residents or staff.', access_notes_it='Proprietà privata: osserva con rispetto dallo spazio pubblico senza disturbare residenti o personale.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-A7CB3CA9' AND category='ODDITY';
