UPDATE places SET description_en='Scoop House is a narrow contemporary house whose curved openings and carved-out forms respond to a constrained site near Bermondsey. Its sculptural façade is visible from the street, but the building is a private home rather than an architectural attraction with interior access.', description_it='Scoop House è una stretta casa contemporanea le cui aperture curve e forme scavate rispondono a un lotto limitato vicino a Bermondsey. La facciata scultorea è visibile dalla strada, ma l’edificio è un’abitazione privata e non un’attrazione architettonica visitabile.', editorial_hook_en='Scoop House: Scoop House is a narrow contemporary house whose curved openings and carved-out forms respond to a constrained site near Bermondsey.', editorial_hook_it='Scoop House: Scoop House è una stretta casa contemporanea le cui aperture curve e forme scavate rispondono a un lotto limitato vicino a Bermondsey.', access_notes_en='Private property: view respectfully from public space and do not disturb residents or staff.', access_notes_it='Proprietà privata: osserva con rispetto dallo spazio pubblico senza disturbare residenti o personale.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-8485BEB4' AND category='ODDITY';
