UPDATE places SET description_en='Pablo Reinoso’s public sculpture makes a familiar bench or structural element appear to escape into curling wooden lines. The work destabilises the boundary between functional street furniture and drawing in space, rewarding views from several angles.', description_it='La scultura pubblica di Pablo Reinoso fa sembrare che una panchina o un elemento strutturale fugga in linee di legno ricurve. L’opera destabilizza il confine tra arredo funzionale e disegno nello spazio, e va osservata da più angolazioni.', editorial_hook_en='Sculpture by Pablo Reinoso: Pablo Reinoso’s public sculpture makes a familiar bench or structural element appear to escape into curling wooden lines.', editorial_hook_it='Sculpture by Pablo Reinoso: La scultura pubblica di Pablo Reinoso fa sembrare che una panchina o un elemento strutturale fugga in linee di legno ricurve.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-B666DB94' AND category='ODDITY';
