UPDATE places SET description_en='Carting Lane’s ornate lamp is associated with a Victorian system that drew sewer gas upward to be burned for street lighting and ventilation. The surviving post is often called London’s last sewer-gas lamp, though its mechanism and fuel were modified over time.', description_it='L’elegante lampione di Carting Lane è legato a un sistema vittoriano che convogliava verso l’alto i gas fognari per bruciarli e illuminare ventilando. È spesso chiamato l’ultimo lampione a gas di fogna di Londra, anche se meccanismo e combustibile cambiarono nel tempo.', editorial_hook_en='Sewer Lamp: Carting Lane’s ornate lamp is associated with a Victorian system that drew sewer gas upward to be burned for street lighting and ventilation.', editorial_hook_it='Sewer Lamp: L’elegante lampione di Carting Lane è legato a un sistema vittoriano che convogliava verso l’alto i gas fognari per bruciarli e illuminare ventilando.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.atlasobscura.com/places/carting-lane-sewer-gas-lamp' WHERE id='O10' AND category='ODDITY';
