UPDATE places SET description_en='Shapes in the Clouds is a playful public artwork that uses elevated forms to frame or echo the changing sky. Its appearance depends on viewpoint, daylight and weather, making the surrounding clouds an active part of the composition rather than a fixed background.', description_it='Shapes in the Clouds è un’opera pubblica giocosa che usa forme elevate per incorniciare o riecheggiare il cielo mutevole. L’aspetto dipende da punto di vista, luce e meteo, rendendo le nuvole una parte attiva della composizione e non uno sfondo fisso.', editorial_hook_en='Shapes in the Clouds: Shapes in the Clouds is a playful public artwork that uses elevated forms to frame or echo the changing sky.', editorial_hook_it='Shapes in the Clouds: Shapes in the Clouds è un’opera pubblica giocosa che usa forme elevate per incorniciare o riecheggiare il cielo mutevole.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-2A1A5F2B' AND category='ODDITY';
