UPDATE places SET description_en='Architect Jaimie Shorten’s Sharks! placed large shark sculptures in the Regent’s Canal as a deliberately absurd response to planning and public-space rules. The fins and bodies appear to invade the water beside Haggerston, turning bureaucratic friction into surreal public art.', description_it='Sharks! dell’architetto Jaimie Shorten colloca grandi squali nel Regent’s Canal come risposta volutamente assurda alle regole urbanistiche e dello spazio pubblico. Pinne e corpi sembrano invadere l’acqua vicino a Haggerston, trasformando l’attrito burocratico in arte surreale.', editorial_hook_en='Sharks!: Architect Jaimie Shorten’s Sharks! placed large shark sculptures in the Regent’s Canal as a deliberately absurd response to planning and public-space rules.', editorial_hook_it='Sharks!: Sharks! dell’architetto Jaimie Shorten colloca grandi squali nel Regent’s Canal come risposta volutamente assurda alle regole urbanistiche e dello spazio pubblico.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-5365A20F' AND category='ODDITY';
