UPDATE places SET description_en='Shepperton Lock is a working Thames navigation lock where the old passenger ferry, riverside paths and boating life meet. The mapped ‘barcarolo’ interest is the small-scale river crossing and lock activity, both dependent on water conditions rather than fixed attraction hours.', description_it='Shepperton Lock è una chiusa operativa del Tamigi dove si incontrano traghetto passeggeri, sentieri fluviali e vita nautica. L’interesse indicato come “barcarolo” riguarda la piccola traversata e l’attività della chiusa, entrambe dipendenti dalle condizioni dell’acqua più che da orari fissi.', editorial_hook_en='Shepperton Lock: Shepperton Lock is a working Thames navigation lock where the old passenger ferry, riverside paths and boating life meet.', editorial_hook_it='Shepperton Lock: Shepperton Lock è una chiusa operativa del Tamigi dove si incontrano traghetto passeggeri, sentieri fluviali e vita nautica.', access_notes_en='Access is seasonal or limited to selected open days; confirm the current programme before travelling.', access_notes_it='L’accesso è stagionale o limitato a giornate specifiche: verifica il programma prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-0FF946EF' AND category='ODDITY';
