UPDATE places SET description_en='The Sherling Backstage Walkway at the National Theatre exposes scenery workshops and backstage circulation through a public route. It reveals theatre as manufacturing—sets, paint, props and logistics—rather than only the finished performance seen from an auditorium.', description_it='La Sherling Backstage Walkway del National Theatre espone laboratori scenografici e percorsi dietro le quinte lungo un itinerario pubblico. Mostra il teatro come produzione—scene, pittura, oggetti e logistica—e non soltanto come spettacolo finito visto dalla platea.', editorial_hook_en='Sherling Backstage Walkway: The Sherling Backstage Walkway at the National Theatre exposes scenery workshops and backstage circulation through a public route.', editorial_hook_it='Sherling Backstage Walkway: La Sherling Backstage Walkway del National Theatre espone laboratori scenografici e percorsi dietro le quinte lungo un itinerario pubblico.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.nationaltheatre.org.uk/your-visit/sherling-backstage-walkway/' WHERE id='LA-86D26E34' AND category='ODDITY';
