UPDATE places SET description_en='Shirley Windmill is a restored 1854 tower mill containing much of its original machinery. Volunteer open days explain grain lifting, grinding and wind control inside one of the few surviving large windmills in Greater London.', description_it='Shirley Windmill è un mulino a torre restaurato del 1854 che conserva gran parte dei macchinari originali. Le giornate aperte gestite da volontari spiegano sollevamento del grano, macinazione e controllo del vento in uno dei pochi grandi mulini superstiti della Greater London.', editorial_hook_en='Shirley Windmill: Shirley Windmill is a restored 1854 tower mill containing much of its original machinery.', editorial_hook_it='Shirley Windmill: Shirley Windmill è un mulino a torre restaurato del 1854 che conserva gran parte dei macchinari originali.', access_notes_en='Access is seasonal or limited to selected open days; confirm the current programme before travelling.', access_notes_it='L’accesso è stagionale o limitato a giornate specifiche: verifica il programma prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.shirleywindmill.org.uk/' WHERE id='LA-C24373B7' AND category='ODDITY';
