UPDATE places SET description_en='Ivor Roberts-Jones’s bronze statue presents Winston Churchill standing heavily in Parliament Square, facing the Palace of Westminster. The simplified mass, walking stick and famously stern posture became the model for many later public images of the wartime prime minister.', description_it='La statua bronzea di Ivor Roberts-Jones presenta Winston Churchill in posizione massiccia a Parliament Square, rivolto verso Westminster. La massa semplificata, il bastone e la celebre postura severa divennero modello per molte immagini pubbliche successive del primo ministro di guerra.', editorial_hook_en='Sir Winston Churchill Statue: Ivor Roberts-Jones’s bronze statue presents Winston Churchill standing heavily in Parliament Square, facing the Palace of Westminster.', editorial_hook_it='Sir Winston Churchill Statue: La statua bronzea di Ivor Roberts-Jones presenta Winston Churchill in posizione massiccia a Parliament Square, rivolto verso Westminster.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-26AD1A00' AND category='ODDITY';
