UPDATE places SET description_en='One of Rick Buckley’s small plaster noses projects anonymously from a Soho façade. Installed in 1997 as a protest against surveillance cameras, the noses acquired elaborate false legends; their almost invisible scale is central to the joke.', description_it='Uno dei piccoli nasi in gesso di Rick Buckley sporge anonimamente da una facciata di Soho. Installati nel 1997 come protesta contro le telecamere, i nasi generarono elaborate leggende false; la scala quasi invisibile è parte essenziale della battuta.', editorial_hook_en='Soho Nose 1: One of Rick Buckley’s small plaster noses projects anonymously from a Soho façade.', editorial_hook_it='Soho Nose 1: Uno dei piccoli nasi in gesso di Rick Buckley sporge anonimamente da una facciata di Soho.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-FB52F5AA' AND category='ODDITY';
