UPDATE places SET description_en='This is another surviving Soho nose from Rick Buckley’s 1997 anti-surveillance intervention. Look above normal eye level for the small cast form embedded in the architecture; it is easily mistaken for ordinary ornament.', description_it='Questo è un altro naso di Soho superstite dell’intervento anti-sorveglianza di Rick Buckley del 1997. Cerca sopra il normale livello degli occhi la piccola forma incorporata nell’architettura, facilmente scambiata per un ornamento comune.', editorial_hook_en='Soho Nose 2: This is another surviving Soho nose from Rick Buckley’s 1997 anti-surveillance intervention.', editorial_hook_it='Soho Nose 2: Questo è un altro naso di Soho superstite dell’intervento anti-sorveglianza di Rick Buckley del 1997.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-814F8869' AND category='ODDITY';
