UPDATE places SET description_en='A discreet plaster nose by Rick Buckley hides on this Soho building, one of several installed without permission in 1997. The work’s anonymity encouraged myths about spies, artists and the Seven Noses of Soho.', description_it='Un discreto naso in gesso di Rick Buckley si nasconde su questo edificio di Soho, uno dei vari installati senza permesso nel 1997. L’anonimato dell’opera alimentò miti su spie, artisti e i Seven Noses of Soho.', editorial_hook_en='Soho Nose 3: A discreet plaster nose by Rick Buckley hides on this Soho building, one of several installed without permission in 1997.', editorial_hook_it='Soho Nose 3: Un discreto naso in gesso di Rick Buckley si nasconde su questo edificio di Soho, uno dei vari installati senza permesso nel 1997.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-0EF8D02D' AND category='ODDITY';
