UPDATE places SET description_en='This tiny facial fragment belongs to Rick Buckley’s group of Soho noses, created as a response to increasing CCTV surveillance. Its placement turns the building itself into a face watching the street.', description_it='Questo minuscolo frammento facciale appartiene al gruppo di nasi di Soho di Rick Buckley, creato in risposta all’aumento della videosorveglianza. La posizione trasforma l’edificio stesso in un volto che osserva la strada.', editorial_hook_en='Soho Nose 4: This tiny facial fragment belongs to Rick Buckley’s group of Soho noses, created as a response to increasing CCTV surveillance.', editorial_hook_it='Soho Nose 4: Questo minuscolo frammento facciale appartiene al gruppo di nasi di Soho di Rick Buckley, creato in risposta all’aumento della videosorveglianza.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-29A0C7D1' AND category='ODDITY';
