UPDATE places SET description_en='One of the remaining Soho noses is attached high on this façade, part of Rick Buckley’s unannounced 1997 street-art project. Finding it requires slow observation rather than following a large monument.', description_it='Uno dei nasi di Soho rimasti è fissato in alto su questa facciata, parte del progetto di street art non annunciato di Rick Buckley del 1997. Trovarlo richiede osservazione lenta invece di seguire un grande monumento.', editorial_hook_en='Soho Nose 5: One of the remaining Soho noses is attached high on this façade, part of Rick Buckley’s unannounced 1997 street-art project.', editorial_hook_it='Soho Nose 5: Uno dei nasi di Soho rimasti è fissato in alto su questa facciata, parte del progetto di street art non annunciato di Rick Buckley del 1997.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-2C691CC2' AND category='ODDITY';
