UPDATE places SET description_en='This nose extends Rick Buckley’s 1997 intervention beyond the most familiar Soho streets. Like the others, the small cast feature critiques urban surveillance while hiding in plain sight among architectural details.', description_it='Questo naso estende l’intervento del 1997 di Rick Buckley oltre le vie più note di Soho. Come gli altri, la piccola forma critica la sorveglianza urbana nascondendosi in piena vista tra i dettagli architettonici.', editorial_hook_en='Soho Nose 6: This nose extends Rick Buckley’s 1997 intervention beyond the most familiar Soho streets.', editorial_hook_it='Soho Nose 6: Questo naso estende l’intervento del 1997 di Rick Buckley oltre le vie più note di Soho.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-14813A43' AND category='ODDITY';
