UPDATE places SET description_en='A final mapped example of Rick Buckley’s Soho noses appears on this Covent Garden façade. The modest projection demonstrates how the project spread through central London and became folklore before its maker publicly explained it.', description_it='Un ultimo esempio cartografato dei nasi di Rick Buckley appare su questa facciata di Covent Garden. La piccola sporgenza mostra come il progetto si diffuse nel centro di Londra e divenne folklore prima che l’autore lo spiegasse pubblicamente.', editorial_hook_en='Soho Nose 7: A final mapped example of Rick Buckley’s Soho noses appears on this Covent Garden façade.', editorial_hook_it='Soho Nose 7: Un ultimo esempio cartografato dei nasi di Rick Buckley appare su questa facciata di Covent Garden.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-C899E589' AND category='ODDITY';
