UPDATE places SET description_en='The glass-covered remains beside Spitalfields Market are a medieval charnel house built to store bones cleared from the cemetery of St Mary Spital. Its subterranean arches survive beneath the modern square, making death and redevelopment visibly overlap.', description_it='I resti protetti dal vetro accanto a Spitalfields Market appartengono a un ossario medievale costruito per conservare le ossa rimosse dal cimitero di St Mary Spital. Gli archi sotterranei sopravvivono sotto la piazza moderna, sovrapponendo visibilmente morte e riqualificazione.', editorial_hook_en='Spitalfields Charnel House: The glass-covered remains beside Spitalfields Market are a medieval charnel house built to store bones cleared from the cemetery of St Mary Spital.', editorial_hook_it='Spitalfields Charnel House: I resti protetti dal vetro accanto a Spitalfields Market appartengono a un ossario medievale costruito per conservare le ossa rimosse dal cimitero di St Mary Spital.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-1310FF8E' AND category='ODDITY';
