UPDATE places SET description_en='St Martin-in-the-Fields is James Gibbs’s influential eighteenth-century church, whose classical portico and steeple were widely copied. Its crypt now contains a café and brass-rubbing centre, while concerts and social programmes keep the building active beyond worship.', description_it='St Martin-in-the-Fields è l’influente chiesa settecentesca di James Gibbs, con portico classico e campanile ampiamente imitati. La cripta ospita oggi caffè e brass rubbing, mentre concerti e programmi sociali mantengono l’edificio attivo oltre il culto.', editorial_hook_en='St Martin-in-the-Fields Church: St Martin-in-the-Fields is James Gibbs’s influential eighteenth-century church, whose classical portico and steeple were widely copied.', editorial_hook_it='St Martin-in-the-Fields Church: St Martin-in-the-Fields è l’influente chiesa settecentesca di James Gibbs, con portico classico e campanile ampiamente imitati.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-15651BB5' AND category='ODDITY';
