UPDATE places SET description_en='A vivid blue door beside St Vedast-alias-Foster leads into a small courtyard hidden among City streets. The colour and compressed passage create a theatrical threshold to the Wren church’s quieter rear spaces.', description_it='Una vivace porta blu accanto a St Vedast-alias-Foster conduce a un piccolo cortile nascosto tra le strade della City. Il colore e il passaggio compresso creano una soglia teatrale verso gli spazi più tranquilli dietro la chiesa di Wren.', editorial_hook_en='St Vedast/Foster - Blue door courtyard: A vivid blue door beside St Vedast-alias-Foster leads into a small courtyard hidden among City streets.', editorial_hook_it='St Vedast/Foster - Blue door courtyard: Una vivace porta blu accanto a St Vedast-alias-Foster conduce a un piccolo cortile nascosto tra le strade della City.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-1C2C5A4A' AND category='ODDITY';
