UPDATE places SET description_en='The Artist’s Garden is a rooftop public-art space above Temple Underground station. Commissioned installations use planting, sculpture and the open skyline, turning transport infrastructure into a changing exhibition rather than a permanent conventional garden.', description_it='The Artist’s Garden è uno spazio d’arte pubblica sul tetto della stazione Temple. Installazioni commissionate usano piante, sculture e cielo aperto, trasformando l’infrastruttura di trasporto in una mostra mutevole invece di un giardino convenzionale permanente.', editorial_hook_en='The Artist''s Garden: The Artist’s Garden is a rooftop public-art space above Temple Underground station.', editorial_hook_it='The Artist''s Garden: The Artist’s Garden è uno spazio d’arte pubblica sul tetto della stazione Temple.', access_notes_en='Access is seasonal or limited to selected open days; confirm the current programme before travelling.', access_notes_it='L’accesso è stagionale o limitato a giornate specifiche: verifica il programma prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://theartistsgarden.org/' WHERE id='LA-1BD5C1CB' AND category='ODDITY';
