UPDATE places SET description_en='The Cenotaph is Edwin Lutyens’s deliberately austere memorial to the dead of the First World War and later conflicts. Its apparently simple geometry subtly curves and tapers, creating a symbolic empty tomb rather than a literal military sculpture.', description_it='The Cenotaph è il memoriale volutamente austero di Edwin Lutyens ai caduti della Prima guerra mondiale e dei conflitti successivi. La geometria apparentemente semplice curva e si assottiglia con discrezione, creando una tomba simbolica vuota invece di una scultura militare letterale.', editorial_hook_en='The Cenotaph: The Cenotaph is Edwin Lutyens’s deliberately austere memorial to the dead of the First World War and later conflicts.', editorial_hook_it='The Cenotaph: The Cenotaph è il memoriale volutamente austero di Edwin Lutyens ai caduti della Prima guerra mondiale e dei conflitti successivi.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-4C8F774F' AND category='ODDITY';
