UPDATE places SET description_en='The Golden Hinde is a full-size reconstruction of the ship in which Francis Drake circumnavigated the globe. Moored in a confined Southwark dock, its compact decks reveal the cramped scale of sixteenth-century ocean travel, though the vessel itself dates from the twentieth century.', description_it='The Golden Hinde è una ricostruzione a grandezza naturale della nave con cui Francis Drake circumnavigò il globo. Ormeggiata in un piccolo bacino di Southwark, mostra la scala angusta dei viaggi oceanici cinquecenteschi, anche se la nave attuale è del Novecento.', editorial_hook_en='The Golden Hinde: The Golden Hinde is a full-size reconstruction of the ship in which Francis Drake circumnavigated the globe.', editorial_hook_it='The Golden Hinde: The Golden Hinde è una ricostruzione a grandezza naturale della nave con cui Francis Drake circumnavigò il globo.', access_notes_en='Interior access is scheduled, ticketed or event-led; check the official venue before travelling.', access_notes_it='L’accesso interno è programmato, a pagamento o legato a eventi: controlla il sito ufficiale prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.goldenhinde.co.uk/' WHERE id='LA-EE096284' AND category='ODDITY';
