UPDATE places SET description_en='Leake Street Arches became a legal graffiti space after Banksy’s 2008 Cans Festival. Layers are constantly painted over, so the tunnel is a live working surface where change, fumes and active artists are part of the experience.', description_it='Leake Street Arches divenne spazio legale per graffiti dopo il Cans Festival di Banksy del 2008. Gli strati vengono continuamente coperti: il tunnel è una superficie attiva dove cambiamento, odori di vernice e artisti al lavoro fanno parte dell’esperienza.', editorial_hook_en='The Graffiti Tunnel: Leake Street Arches became a legal graffiti space after Banksy’s 2008 Cans Festival.', editorial_hook_it='The Graffiti Tunnel: Leake Street Arches divenne spazio legale per graffiti dopo il Cans Festival di Banksy del 2008.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-4385553D' AND category='ODDITY';
