UPDATE places SET description_en='The Hardy Tree grew among gravestones moved during the expansion of St Pancras railway, traditionally associated with the young Thomas Hardy’s work for an architect. The original ash collapsed after decay, but the site and stones preserve the powerful image and its railway-era story.', description_it='The Hardy Tree crebbe tra lapidi spostate durante l’ampliamento della ferrovia di St Pancras, tradizionalmente legate al lavoro del giovane Thomas Hardy per un architetto. Il frassino originale è crollato dopo il degrado, ma luogo e pietre conservano l’immagine e la storia ferroviaria.', editorial_hook_en='The Hardy Tree: The Hardy Tree grew among gravestones moved during the expansion of St Pancras railway, traditionally associated with the young Thomas Hardy’s work for an architect.', editorial_hook_it='The Hardy Tree: The Hardy Tree crebbe tra lapidi spostate durante l’ampliamento della ferrovia di St Pancras, tradizionalmente legate al lavoro del giovane Thomas Hardy per un architetto.', access_notes_en='The original work or attraction is no longer present; this record documents its former location.', access_notes_it='L’opera o attrazione originale non è più presente: questo record ne documenta la posizione storica.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-D0D879FB' AND category='ODDITY';
