UPDATE places SET description_en='The Hill Garden and Pergola is an elevated Edwardian walkway built for Lord Leverhulme above Hampstead Heath. Brick terraces, classical columns and climbing plants create long framed views, with weathering adding a romantic sense of partial ruin.', description_it='The Hill Garden and Pergola è una passeggiata edoardiana sopraelevata costruita per Lord Leverhulme sopra Hampstead Heath. Terrazze in mattoni, colonne classiche e rampicanti creano lunghe viste incorniciate, mentre l’usura aggiunge un romantico senso di rovina parziale.', editorial_hook_en='The Hill Garden and Pergola: The Hill Garden and Pergola is an elevated Edwardian walkway built for Lord Leverhulme above Hampstead Heath.', editorial_hook_it='The Hill Garden and Pergola: The Hill Garden and Pergola è una passeggiata edoardiana sopraelevata costruita per Lord Leverhulme sopra Hampstead Heath.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.cityoflondon.gov.uk/things-to-do/green-spaces/hampstead-heath/where-to-go-at-hampstead-heath/hill-garden-and-pergola' WHERE id='LA-9C651CC8' AND category='ODDITY';
