UPDATE places SET description_en='The House Mill at Three Mills is a major surviving tidal mill, rebuilt in 1776 on a much older milling site. Water wheels once drove machinery for flour and alcohol production; guided visits reveal the timber mechanisms and industrial landscape of the lower Lea.', description_it='The House Mill a Three Mills è un grande mulino a marea superstite, ricostruito nel 1776 su un sito molto più antico. Le ruote idrauliche azionavano macchinari per farina e alcol; le visite guidate mostrano meccanismi in legno e paesaggio industriale del basso Lea.', editorial_hook_en='The House Mill: The House Mill at Three Mills is a major surviving tidal mill, rebuilt in 1776 on a much older milling site.', editorial_hook_it='The House Mill: The House Mill a Three Mills è un grande mulino a marea superstite, ricostruito nel 1776 su un sito molto più antico.', access_notes_en='Access is seasonal or limited to selected open days; confirm the current programme before travelling.', access_notes_it='L’accesso è stagionale o limitato a giornate specifiche: verifica il programma prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.housemill.org.uk/' WHERE id='LA-9AC09376' AND category='ODDITY';
