UPDATE places SET description_en='This distinctive postbox is valued for an unusual royal cipher, design detail or survival within the local streetscape. Inspect the casting and collection plate closely: small differences identify the reign and period more reliably than colour alone.', description_it='Questa caratteristica cassetta postale è notevole per un insolito monogramma reale, dettaglio di design o sopravvivenza nel paesaggio locale. Osserva fusione e targhetta di raccolta: piccole differenze identificano regno ed epoca meglio del solo colore.', editorial_hook_en='The Iconic postbox: This distinctive postbox is valued for an unusual royal cipher, design detail or survival within the local streetscape.', editorial_hook_it='The Iconic postbox: Questa caratteristica cassetta postale è notevole per un insolito monogramma reale, dettaglio di design o sopravvivenza nel paesaggio locale.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-DEAF5706' AND category='ODDITY';
