UPDATE places SET description_en='Artist Carrie Reichardt has covered her Chiswick home with mosaics, ceramics, slogans and portraits created with collaborators. The façade turns a private suburban house into a dense public artwork addressing activism, community and social justice; view it respectfully from the pavement.', description_it='L’artista Carrie Reichardt ha coperto la propria casa di Chiswick con mosaici, ceramiche, slogan e ritratti creati con collaboratori. La facciata trasforma un’abitazione suburbana privata in una fitta opera pubblica su attivismo, comunità e giustizia sociale; va osservata con rispetto dal marciapiede.', editorial_hook_en='The Mosaic House Chiswick: Artist Carrie Reichardt has covered her Chiswick home with mosaics, ceramics, slogans and portraits created with collaborators.', editorial_hook_it='The Mosaic House Chiswick: L’artista Carrie Reichardt ha coperto la propria casa di Chiswick con mosaici, ceramiche, slogan e ritratti creati con collaboratori.', access_notes_en='Private property: view respectfully from public space and do not disturb residents or staff.', access_notes_it='Proprietà privata: osserva con rispetto dallo spazio pubblico senza disturbare residenti o personale.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.carriereichardt.com/' WHERE id='LA-F4CBE9DC' AND category='ODDITY';
