UPDATE places SET description_en='The Nursemaids’ Tunnel is a pedestrian passage beneath Marylebone Road linking parts of the former estate landscape around Regent’s Park. Its name recalls the carers and children who used such segregated routes to cross busy roads away from carriage traffic.', description_it='The Nursemaids’ Tunnel è un passaggio pedonale sotto Marylebone Road che collega parti dell’antico paesaggio di Regent’s Park. Il nome ricorda bambinaie e bambini che usavano percorsi separati per attraversare strade trafficate lontano dalle carrozze.', editorial_hook_en='The Nursemaids'' Tunnel: The Nursemaids’ Tunnel is a pedestrian passage beneath Marylebone Road linking parts of the former estate landscape around Regent’s Park.', editorial_hook_it='The Nursemaids'' Tunnel: The Nursemaids’ Tunnel è un passaggio pedonale sotto Marylebone Road che collega parti dell’antico paesaggio di Regent’s Park.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-B462351E' AND category='ODDITY';
