UPDATE places SET description_en='The timber-framed building known as The Old Curiosity Shop dates largely from the sixteenth or seventeenth century and survived nearby redevelopment. Its Dickens association was applied after the novel rather than firmly proven, but the tiny shop remains a rare fragment of pre-Fire London.', description_it='L’edificio a graticcio noto come The Old Curiosity Shop risale in gran parte al XVI o XVII secolo ed è sopravvissuto alla riqualificazione circostante. Il legame con Dickens fu attribuito dopo il romanzo e non è provato, ma il piccolo negozio resta un raro frammento della Londra precedente al Grande Incendio.', editorial_hook_en='The Old Curiosity Shop: The timber-framed building known as The Old Curiosity Shop dates largely from the sixteenth or seventeenth century and survived nearby redevelopment.', editorial_hook_it='The Old Curiosity Shop: L’edificio a graticcio noto come The Old Curiosity Shop risale in gran parte al XVI o XVII secolo ed è sopravvissuto alla riqualificazione circostante.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-2135F164' AND category='ODDITY';
