UPDATE places SET description_en='Thomas Heatherwick’s Rolling Bridge curls its eight steel-and-timber sections into a wheel to open the head of Paddington Basin. It is a kinetic sculpture that also functions as a footbridge, but demonstrations occur only at scheduled times.', description_it='Il Rolling Bridge di Thomas Heatherwick arrotola otto sezioni in acciaio e legno formando una ruota per aprire il bacino di Paddington. È una scultura cinetica che funziona anche da passerella, ma le dimostrazioni avvengono solo in orari programmati.', editorial_hook_en='The Rolling Bridge: Thomas Heatherwick’s Rolling Bridge curls its eight steel-and-timber sections into a wheel to open the head of Paddington Basin.', editorial_hook_it='The Rolling Bridge: Il Rolling Bridge di Thomas Heatherwick arrotola otto sezioni in acciaio e legno formando una ruota per aprire il bacino di Paddington.', access_notes_en='Access is seasonal or limited to selected open days; confirm the current programme before travelling.', access_notes_it='L’accesso è stagionale o limitato a giornate specifiche: verifica il programma prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-E0BD8587' AND category='ODDITY';
