UPDATE places SET description_en='The Thames Barrier uses ten movable steel gates to protect London from tidal surges. When raised, the silver piers and rotating gates reveal flood defence as monumental river engineering; the riverside information centre explains forecasts and closures.', description_it='The Thames Barrier usa dieci paratoie mobili in acciaio per proteggere Londra dalle maree eccezionali. Quando si alzano, piloni argentati e porte rotanti mostrano la difesa dalle inondazioni come ingegneria monumentale; il centro informativo spiega previsioni e chiusure.', editorial_hook_en='The Thames Barrier: The Thames Barrier uses ten movable steel gates to protect London from tidal surges.', editorial_hook_it='The Thames Barrier: The Thames Barrier usa dieci paratoie mobili in acciaio per proteggere Londra dalle maree eccezionali.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.gov.uk/guidance/the-thames-barrier' WHERE id='O1' AND category='ODDITY';
