UPDATE places SET description_en='The Tide is an elevated landscaped walkway winding through Greenwich Peninsula. Ramps, bridges and planting create changing Thames views while public artworks punctuate the route, combining park, promenade and infrastructure above the surrounding streets.', description_it='The Tide è una passeggiata paesaggistica sopraelevata che attraversa Greenwich Peninsula. Rampe, ponti e piante creano vedute mutevoli sul Tamigi, intervallate da opere pubbliche, unendo parco, promenade e infrastruttura sopra le strade circostanti.', editorial_hook_en='The Tide: The Tide is an elevated landscaped walkway winding through Greenwich Peninsula.', editorial_hook_it='The Tide: The Tide è una passeggiata paesaggistica sopraelevata che attraversa Greenwich Peninsula.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-0F64E87F' AND category='ODDITY';
