UPDATE places SET description_en='Kilburn’s Tin Tabernacle is a corrugated-iron church erected in 1863 and later converted into the Sea Cadets’ HMS Bicester. Behind the fragile metal exterior, a mock ship interior and nautical fittings create an extraordinary collision of chapel and training vessel.', description_it='Il Tin Tabernacle di Kilburn è una chiesa in lamiera ondulata eretta nel 1863 e poi trasformata nella sede dei Sea Cadets HMS Bicester. Dietro il fragile esterno metallico, interni da nave e arredi nautici creano uno straordinario incontro tra cappella e unità d’addestramento.', editorial_hook_en='The Tin Tabernacle: Kilburn’s Tin Tabernacle is a corrugated-iron church erected in 1863 and later converted into the Sea Cadets’ HMS Bicester.', editorial_hook_it='The Tin Tabernacle: Il Tin Tabernacle di Kilburn è una chiesa in lamiera ondulata eretta nel 1863 e poi trasformata nella sede dei Sea Cadets HMS Bicester.', access_notes_en='Access is seasonal or limited to selected open days; confirm the current programme before travelling.', access_notes_it='L’accesso è stagionale o limitato a giornate specifiche: verifica il programma prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.thetintabernacle.org.uk/' WHERE id='LA-491A3AE6' AND category='ODDITY';
