UPDATE places SET description_en='This South Kensington ‘thin house’ uses a triangular plot created by converging streets. The end façade is only a few feet deep, while the building widens behind it, producing a convincing architectural illusion when seen head-on.', description_it='Questa “thin house” di South Kensington sfrutta un lotto triangolare creato da strade convergenti. La facciata terminale è profonda pochi piedi, mentre l’edificio si allarga dietro, producendo una convincente illusione architettonica vista frontalmente.', editorial_hook_en='Thin House: This South Kensington ‘thin house’ uses a triangular plot created by converging streets.', editorial_hook_it='Thin House: Questa “thin house” di South Kensington sfrutta un lotto triangolare creato da strade convergenti.', access_notes_en='Private property: view respectfully from public space and do not disturb residents or staff.', access_notes_it='Proprietà privata: osserva con rispetto dallo spazio pubblico senza disturbare residenti o personale.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-13286267' AND category='ODDITY';
