UPDATE places SET description_en='Brunel’s Three Bridges at Hanwell stacks road, canal and railway at one junction: Windmill Lane above the Grand Union Canal, which crosses the railway in an iron trough. The compact composition solved three competing routes without an ordinary level crossing.', description_it='Three Bridges di Brunel a Hanwell sovrappone strada, canale e ferrovia in un solo nodo: Windmill Lane sopra il Grand Union Canal, che attraversa i binari in una vasca di ferro. La composizione risolse tre percorsi concorrenti senza un normale passaggio a livello.', editorial_hook_en='Three Bridges: Brunel’s Three Bridges at Hanwell stacks road, canal and railway at one junction: Windmill Lane above the Grand Union Canal, which crosses the railway in an iron trough.', editorial_hook_it='Three Bridges: Three Bridges di Brunel a Hanwell sovrappone strada, canale e ferrovia in un solo nodo: Windmill Lane sopra il Grand Union Canal, che attraversa i binari in una vasca di ferro.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.discoveringbritain.org/activities/greater-london/viewpoints/three-bridges.html' WHERE id='O13' AND category='ODDITY';
