UPDATE places SET description_en='Tiny Wee Gallery compresses an independent art display into a window-sized space on a Spitalfields street. Changing work is viewed from the pavement rather than through a conventional staffed interior, making scale and accidental discovery central to the project.', description_it='Tiny Wee Gallery concentra una mostra indipendente in uno spazio delle dimensioni di una vetrina a Spitalfields. Le opere cambiano e si osservano dal marciapiede invece che in un interno con personale, rendendo scala ridotta e scoperta casuale parti centrali del progetto.', editorial_hook_en='Tiny Wee Gallery: Tiny Wee Gallery compresses an independent art display into a window-sized space on a Spitalfields street.', editorial_hook_it='Tiny Wee Gallery: Tiny Wee Gallery concentra una mostra indipendente in uno spazio delle dimensioni di una vetrina a Spitalfields.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-261025-01' AND category='ODDITY';
