UPDATE places SET description_en='Pierre Vivant’s Traffic Light Tree combines seventy-five sets of traffic lights into a branching public sculpture near Canary Wharf. Computer-controlled sequences replace practical road instructions with restless colour, turning familiar signals into an urban tree.', description_it='Traffic Light Tree di Pierre Vivant combina settantacinque gruppi semaforici in una scultura ramificata vicino a Canary Wharf. Sequenze controllate dal computer sostituiscono le istruzioni stradali con colori irrequieti, trasformando segnali familiari in un albero urbano.', editorial_hook_en='Traffic Light Tree: Pierre Vivant’s Traffic Light Tree combines seventy-five sets of traffic lights into a branching public sculpture near Canary Wharf.', editorial_hook_it='Traffic Light Tree: Traffic Light Tree di Pierre Vivant combina settantacinque gruppi semaforici in una scultura ramificata vicino a Canary Wharf.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-DD65BB87' AND category='ODDITY';
