UPDATE places SET description_en='Trinity Buoy Wharf’s Experimental Lighthouse was built in the 1860s for testing maritime lights and later associated with Michael Faraday’s optical work. It was never a normal navigational lighthouse; today the tower sits within a creative riverside complex and hosts Longplayer.', description_it='L’Experimental Lighthouse di Trinity Buoy Wharf fu costruito negli anni Sessanta dell’Ottocento per provare luci marittime e fu poi associato agli studi ottici di Michael Faraday. Non fu mai un normale faro di navigazione; oggi sorge in un complesso creativo sul fiume e ospita Longplayer.', editorial_hook_en='Trinity Buoy Lighthouse: Trinity Buoy Wharf’s Experimental Lighthouse was built in the 1860s for testing maritime lights and later associated with Michael Faraday’s optical work.', editorial_hook_it='Trinity Buoy Lighthouse: L’Experimental Lighthouse di Trinity Buoy Wharf fu costruito negli anni Sessanta dell’Ottocento per provare luci marittime e fu poi associato agli studi ottici di Michael Faraday.', access_notes_en='Access is seasonal or limited to selected open days; confirm the current programme before travelling.', access_notes_it='L’accesso è stagionale o limitato a giornate specifiche: verifica il programma prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.trinitybuoywharf.com/' WHERE id='O14' AND category='ODDITY';
