UPDATE places SET description_en='Italian poet Ugo Foscolo was first buried at St Nicholas’s churchyard in Chiswick after dying in exile in 1827. His remains were later transferred to Santa Croce in Florence, leaving the original grave as a marker of displacement, memory and Anglo-Italian literary history.', description_it='Il poeta italiano Ugo Foscolo fu sepolto inizialmente nel cimitero di St Nicholas a Chiswick dopo la morte in esilio nel 1827. Le spoglie furono poi trasferite a Santa Croce a Firenze, lasciando la prima tomba come segno di esilio, memoria e storia letteraria anglo-italiana.', editorial_hook_en='Ugo Foscolo''s first grave: Italian poet Ugo Foscolo was first buried at St Nicholas’s churchyard in Chiswick after dying in exile in 1827.', editorial_hook_it='Ugo Foscolo''s first grave: Il poeta italiano Ugo Foscolo fu sepolto inizialmente nel cimitero di St Nicholas a Chiswick dopo la morte in esilio nel 1827.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-6E579DBB' AND category='ODDITY';
