UPDATE places SET description_en='The stone on the Thames path marks the finish line of the annual Oxford–Cambridge Boat Race. Its modest size contrasts with the event’s scale, fixing an invisible line across the river where closely fought races are decided.', description_it='La pietra sul Thames Path indica il traguardo dell’annuale Boat Race Oxford–Cambridge. Le dimensioni modeste contrastano con la portata dell’evento, fissando una linea invisibile attraverso il fiume dove si decidono gare spesso serrate.', editorial_hook_en='University Boat Race Finishing Stone: The stone on the Thames path marks the finish line of the annual Oxford–Cambridge Boat Race.', editorial_hook_it='University Boat Race Finishing Stone: La pietra sul Thames Path indica il traguardo dell’annuale Boat Race Oxford–Cambridge.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-CDD0946C' AND category='ODDITY';
