UPDATE places SET description_en='Up at The O2 is a guided climb over the fabric roof of the former Millennium Dome. Visitors wear harnesses and follow a suspended walkway to a central platform, experiencing the building’s cable-supported structure as terrain rather than seeing it only from below.', description_it='Up at The O2 è una salita guidata sul tetto in tessuto dell’ex Millennium Dome. Con imbracature, i visitatori seguono una passerella sospesa fino alla piattaforma centrale, vivendo la struttura sostenuta da cavi come terreno invece di osservarla soltanto dal basso.', editorial_hook_en='Up at The O2: Up at The O2 is a guided climb over the fabric roof of the former Millennium Dome.', editorial_hook_it='Up at The O2: Up at The O2 è una salita guidata sul tetto in tessuto dell’ex Millennium Dome.', access_notes_en='Interior access is scheduled, ticketed or event-led; check the official venue before travelling.', access_notes_it='L’accesso interno è programmato, a pagamento o legato a eventi: controlla il sito ufficiale prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.upattheo2.co.uk/' WHERE id='LA-1425C36D' AND category='ODDITY';
