UPDATE places SET description_en='Upminster Windmill is a smock mill built in 1803 and restored with working machinery, sails and cap. Volunteer open days explain how wind power drove several floors of milling equipment at what was once the rural edge of Essex.', description_it='Upminster Windmill è un mulino a torre lignea costruito nel 1803 e restaurato con macchinari, pale e copertura funzionanti. Le aperture dei volontari spiegano come il vento azionasse più piani di attrezzature in quella che era la campagna dell’Essex.', editorial_hook_en='Upminster Windmill: Upminster Windmill is a smock mill built in 1803 and restored with working machinery, sails and cap.', editorial_hook_it='Upminster Windmill: Upminster Windmill è un mulino a torre lignea costruito nel 1803 e restaurato con macchinari, pale e copertura funzionanti.', access_notes_en='Access is seasonal or limited to selected open days; confirm the current programme before travelling.', access_notes_it='L’accesso è stagionale o limitato a giornate specifiche: verifica il programma prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.upminsterwindmill.org/' WHERE id='LA-9366C9A1' AND category='ODDITY';
