UPDATE places SET description_en='The V2 memorial marks the Chiswick site where a German V2 rocket exploded in September 1944, the first to strike Britain. Its understated plaque anchors the beginning of a new and terrifying form of ballistic warfare to an ordinary residential street.', description_it='Il memoriale V2 indica il punto di Chiswick dove un razzo tedesco V2 esplose nel settembre 1944, il primo a colpire la Gran Bretagna. La sobria targa lega l’inizio di una nuova e terribile guerra balistica a una normale strada residenziale.', editorial_hook_en='V2 Rocket Memorial: The V2 memorial marks the Chiswick site where a German V2 rocket exploded in September 1944, the first to strike Britain.', editorial_hook_it='V2 Rocket Memorial: Il memoriale V2 indica il punto di Chiswick dove un razzo tedesco V2 esplose nel settembre 1944, il primo a colpire la Gran Bretagna.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-839EB2FE' AND category='ODDITY';
