UPDATE places SET description_en='Victoria Park’s Chinese Pagoda is a modern reconstruction of the pavilion first created for the park in the 1840s. Standing on an island reached by an ornamental bridge, it restores an exotic focal point to the lake while clearly dating from a later rebuilding.', description_it='La Chinese Pagoda di Victoria Park è una ricostruzione moderna del padiglione creato per il parco negli anni Quaranta dell’Ottocento. Su un’isola raggiunta da un ponte ornamentale, restituisce al lago un punto focale esotico pur appartenendo chiaramente a una ricostruzione successiva.', editorial_hook_en='Victoria Park Chinese Pagoda: Victoria Park’s Chinese Pagoda is a modern reconstruction of the pavilion first created for the park in the 1840s.', editorial_hook_it='Victoria Park Chinese Pagoda: La Chinese Pagoda di Victoria Park è una ricostruzione moderna del padiglione creato per il parco negli anni Quaranta dell’Ottocento.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-049868CF' AND category='ODDITY';
