UPDATE places SET description_en='The weather vane of St Lawrence Jewry can be seen above the City roofline, its gilded form identifying Wren’s church beside Guildhall. The mapped viewpoint rewards looking upward from the correct street angle rather than entering a separate attraction.', description_it='La banderuola di St Lawrence Jewry si vede sopra i tetti della City e la forma dorata identifica la chiesa di Wren accanto alla Guildhall. Il punto indicato premia lo sguardo verso l’alto dall’angolo giusto della strada, non l’ingresso in un’attrazione separata.', editorial_hook_en='View su Weather vane a St Lawrence Jewry: The weather vane of St Lawrence Jewry can be seen above the City roofline, its gilded form identifying Wren’s church beside Guildhall.', editorial_hook_it='View su Weather vane a St Lawrence Jewry: La banderuola di St Lawrence Jewry si vede sopra i tetti della City e la forma dorata identifica la chiesa di Wren accanto alla Guildhall.', access_notes_en='Visible from public space; opening conditions and temporary restrictions can change.', access_notes_it='Visibile dallo spazio pubblico; condizioni di apertura e limitazioni temporanee possono cambiare.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-BB40B844' AND category='ODDITY';
