UPDATE places SET description_en='Garden Lodge was Freddie Mercury’s Kensington home and remains a private residence. Fans historically left messages on its boundary wall, but the site has no public interior; respectful viewing should avoid obstructing neighbours or treating the entrance as a shrine.', description_it='Garden Lodge fu la casa londinese di Freddie Mercury e resta un’abitazione privata. I fan lasciavano messaggi sul muro di confine, ma non esiste accesso pubblico all’interno; la visita deve rispettare i vicini e non trasformare l’ingresso in un santuario.', editorial_hook_en='Villa Garden Lodge - Freddie Mercury house: Garden Lodge was Freddie Mercury’s Kensington home and remains a private residence.', editorial_hook_it='Villa Garden Lodge - Freddie Mercury house: Garden Lodge fu la casa londinese di Freddie Mercury e resta un’abitazione privata.', access_notes_en='Private property: view respectfully from public space and do not disturb residents or staff.', access_notes_it='Proprietà privata: osserva con rispetto dallo spazio pubblico senza disturbare residenti o personale.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP WHERE id='LA-D05A4C05' AND category='ODDITY';
