UPDATE places SET description_en='Wigmore Hall is an exceptionally intimate 1901 concert hall known for chamber music and song. Its Arts and Crafts interior culminates in a cupola mural above the stage, while famously clear acoustics make subtle performances unusually immediate.', description_it='Wigmore Hall è una sala da concerto del 1901 eccezionalmente intima, celebre per musica da camera e canto. L’interno Arts and Crafts culmina in un dipinto nella cupola sopra il palco, mentre l’acustica limpida rende le esecuzioni più sottili insolitamente immediate.', editorial_hook_en='Wigmore Hall: Wigmore Hall is an exceptionally intimate 1901 concert hall known for chamber music and song.', editorial_hook_it='Wigmore Hall: Wigmore Hall è una sala da concerto del 1901 eccezionalmente intima, celebre per musica da camera e canto.', access_notes_en='Interior access is scheduled, ticketed or event-led; check the official venue before travelling.', access_notes_it='L’accesso interno è programmato, a pagamento o legato a eventi: controlla il sito ufficiale prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.wigmore-hall.org.uk/' WHERE id='LA-4ACACF0C' AND category='ODDITY';
