UPDATE places SET description_en='Wilton’s Music Hall preserves a mid-nineteenth-century auditorium behind a row of older East End houses and pub rooms. Layers of peeling paint, galleries and later repairs reveal survival rather than polished reconstruction, while performances continue the building’s original purpose.', description_it='Wilton’s Music Hall conserva un auditorium ottocentesco dietro una fila di case e locali più antichi dell’East End. Strati di pittura, gallerie e riparazioni successive mostrano sopravvivenza più che ricostruzione patinata, mentre gli spettacoli continuano la funzione originaria.', editorial_hook_en='Wilton''s Music Hall: Wilton’s Music Hall preserves a mid-nineteenth-century auditorium behind a row of older East End houses and pub rooms.', editorial_hook_it='Wilton''s Music Hall: Wilton’s Music Hall conserva un auditorium ottocentesco dietro una fila di case e locali più antichi dell’East End.', access_notes_en='Interior access is scheduled, ticketed or event-led; check the official venue before travelling.', access_notes_it='L’accesso interno è programmato, a pagamento o legato a eventi: controlla il sito ufficiale prima di partire.', last_verified_at='2026-10-28', updated_at=CURRENT_TIMESTAMP, official_url='https://www.wiltons.org.uk/' WHERE id='LA-780DDE54' AND category='ODDITY';
